function _renderRecontactDailyResults(data) {
    const total = data.total || 0;
    if (total === 0) {
        return '<div style="color:#888;font-size:12px;padding:10px;background:rgba(0,0,0,0.20);border-radius:6px;text-align:center;">Sin actividad de tildes en esta fecha.</div>';
    }
    const fmtTime = (t) => {
        try { return new Date(t).toLocaleTimeString('es-AR', { hour:'2-digit', minute:'2-digit' }); }
        catch (_) { return '-'; }
    };
    const actionLabel = (a) => {
        if (a === 'etiqueta') return '📞 Etiqueta';
        if (a === 'wa') return '💬 WA';
        if (a === 'favorito') return '⭐ Favorito';
        if (a.startsWith('respuesta:')) {
            const s = a.split(':')[1] || '';
            return '✓ Respuesta: ' + s;
        }
        return a;
    };
    let html = '';
    // KPIs.
    html += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:6px;margin-bottom:10px;">';
    html += '  <div style="background:rgba(0,0,0,0.25);border-radius:6px;padding:8px 10px;"><div style="color:#888;font-size:10px;text-transform:uppercase;letter-spacing:1px;">Total tildes</div><div style="color:#fff;font-weight:900;font-size:20px;">' + total + '</div></div>';
    html += '  <div style="background:rgba(0,0,0,0.25);border-radius:6px;padding:8px 10px;"><div style="color:#888;font-size:10px;text-transform:uppercase;letter-spacing:1px;">Usuarios únicos</div><div style="color:#fff;font-weight:900;font-size:20px;">' + (data.uniqueUsers || 0) + '</div></div>';
    html += '</div>';

    // Agregados por admin.
    const adminEntries = Object.entries(data.byAdmin || {}).sort((a,b) => b[1] - a[1]);
    if (adminEntries.length > 0) {
        html += '<div style="margin-bottom:10px;">';
        html += '  <div style="color:#c977ff;font-size:11px;text-transform:uppercase;letter-spacing:1px;margin-bottom:4px;">Por personal:</div>';
        html += '  <div style="display:flex;flex-wrap:wrap;gap:6px;">';
        for (const [adm, n] of adminEntries) {
            html += '<div style="background:rgba(155,48,255,0.15);border:1px solid rgba(155,48,255,0.40);color:#fff;padding:4px 10px;border-radius:14px;font-size:11.5px;"><strong>' + escapeHtml(adm) + '</strong>: ' + n + '</div>';
        }
        html += '  </div>';
        html += '</div>';
    }
    // Agregados por acción.
    const actionEntries = Object.entries(data.byAction || {}).sort((a,b) => b[1] - a[1]);
    if (actionEntries.length > 0) {
        html += '<div style="margin-bottom:10px;">';
        html += '  <div style="color:#c977ff;font-size:11px;text-transform:uppercase;letter-spacing:1px;margin-bottom:4px;">Por tipo:</div>';
        html += '  <div style="display:flex;flex-wrap:wrap;gap:6px;">';
        for (const [a, n] of actionEntries) {
            html += '<div style="background:rgba(0,212,255,0.10);border:1px solid rgba(0,212,255,0.30);color:#fff;padding:4px 10px;border-radius:14px;font-size:11.5px;">' + escapeHtml(actionLabel(a)) + ': <strong>' + n + '</strong></div>';
        }
        html += '  </div>';
        html += '</div>';
    }
    // Buscador para filtrar la tabla por username (verificación rápida).
    html += '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:8px;">';
    html += '  <label style="color:#bbb;font-size:11.5px;">🔎 Filtrar por usuario:</label>';
    html += '  <input type="text" id="recontactDailyFilter" placeholder="Ej: lalodj" autocomplete="off" style="flex:1;min-width:180px;background:#0a0a0a;color:#fff;border:1px solid rgba(155,48,255,0.40);padding:6px 10px;border-radius:6px;font-size:12px;">';
    html += '  <span id="recontactDailyFilterCount" style="color:#888;font-size:11px;">' + (data.events || []).length + ' eventos</span>';
    html += '</div>';
    // Tabla de eventos.
    html += '<div style="background:rgba(0,0,0,0.30);border-radius:8px;overflow:hidden;max-height:480px;overflow-y:auto;">';
    html += '<table style="width:100%;border-collapse:collapse;font-size:12px;" id="recontactDailyTable">';
    html += '<thead style="position:sticky;top:0;background:#1a0033;"><tr style="color:#c977ff;text-align:left;">';
    html += '<th style="padding:7px 10px;font-weight:800;">Hora</th>';
    html += '<th style="padding:7px 10px;font-weight:800;">Usuario</th>';
    html += '<th style="padding:7px 10px;font-weight:800;">Acción</th>';
    html += '<th style="padding:7px 10px;font-weight:800;text-align:center;">Estado</th>';
    html += '<th style="padding:7px 10px;font-weight:800;">Personal</th>';
    html += '</tr></thead><tbody>';
    for (const e of (data.events || [])) {
        const stateBadge = e.set
            ? '<span style="color:#66ff66;font-weight:800;">✓ tildado</span>'
            : '<span style="color:#ff8080;font-weight:800;">✗ destildado</span>';
        const u = String(e.username || '').toLowerCase();
        const by = String(e.by || '').toLowerCase();
        html += '<tr data-user="' + escapeHtml(u) + '" data-by="' + escapeHtml(by) + '" style="border-top:1px solid rgba(255,255,255,0.05);">';
        html += '<td style="padding:6px 10px;color:#aaa;font-size:11px;white-space:nowrap;">' + escapeHtml(fmtTime(e.at)) + '</td>';
        html += '<td style="padding:6px 10px;color:#fff;font-weight:700;">' + escapeHtml(e.username || '—') + '</td>';
        html += '<td style="padding:6px 10px;color:#fff;">' + escapeHtml(actionLabel(e.action)) + '</td>';
        html += '<td style="padding:6px 10px;text-align:center;">' + stateBadge + '</td>';
        html += '<td style="padding:6px 10px;color:#c977ff;font-weight:700;">' + escapeHtml(e.by || '—') + '</td>';
        html += '</tr>';
    }
    html += '</tbody></table></div>';
    // Wire del filtro client-side (no hace falta llamar al server).
    setTimeout(() => {
        const inp = document.getElementById('recontactDailyFilter');
        const tbody = document.querySelector('#recontactDailyTable tbody');
        const counter = document.getElementById('recontactDailyFilterCount');
        if (!inp || !tbody) return;
        inp.oninput = () => {
            const q = (inp.value || '').trim().toLowerCase();
            let visible = 0;
            tbody.querySelectorAll('tr').forEach(tr => {
                const u = tr.getAttribute('data-user') || '';
                const by = tr.getAttribute('data-by') || '';
                const match = !q || u.includes(q) || by.includes(q);
                tr.style.display = match ? '' : 'none';
                if (match) visible++;
            });
            if (counter) counter.textContent = visible + ' eventos' + (q ? ' (filtrado)' : '');
        };
    }, 0);
    return html;
}

function loadRecontactSection() {
    const c = document.getElementById('recontactContent');
    if (!c) return;

    // Si ya hay state en memoria (mismo session), renderizar al toque.
    if (_recontactState.items && _recontactState.summary) {
        c.innerHTML = _renderRecontactUserSearch() + _renderRecontactDashboard(_recontactState.summary, _recontactState.items) + _renderRecontactDailyProgress();
        _wireRecontactFilters();
        _wireRecontactSearch();
        _wireRecontactDailyProgress();
        return;
    }

    // Mostrar buscador (siempre arriba) + uploader (con loader chiquito mientras revisamos IDB)
    c.innerHTML = _renderRecontactUserSearch() + _renderRecontactUploader() + _renderRecontactDailyProgress();
    _wireRecontactSearch();
    _wireRecontactDailyProgress();
    const history = _recontactLoadHistory();
    if (history.length > 0) {
        c.innerHTML += _renderRecontactHistoryStandalone(history);
    }

    // Loader visible un instante mientras revisa IDB
    const probe = document.createElement('div');
    probe.id = 'recontactCacheProbe';
    probe.style.cssText = 'position:absolute;top:8px;right:14px;color:#888;font-size:11px;';
    probe.textContent = '🔍 Buscando análisis previo…';
    if (c.firstChild) c.insertBefore(probe, c.firstChild);

    // Refrescar el historial del server en paralelo al cache.
    _recontactRefreshHistory().then(() => {
        // Si todavía estamos en uploader (no hay cache hidratado), re-render
        // para mostrar el historial actualizado debajo.
        if (!_recontactState.items) {
            const stillUploader = c.querySelector('#recontactDropZone');
            if (stillUploader) {
                const newHtml = _renderRecontactUploader();
                const hist = _recontactLoadHistory();
                c.innerHTML = newHtml + (hist.length > 0 ? _renderRecontactHistoryStandalone(hist) : '');
            }
        }
    }).catch(() => {});

    _recontactLoadCache().then(async cache => {
        try { document.getElementById('recontactCacheProbe')?.remove(); } catch (_) {}
        if (!cache) return;
        // Si hay items y summary, hidratar dashboard.
        if (cache.items && cache.summary) {
            _recontactState.items = cache.items;
            _recontactState.summary = cache.summary;
            _recontactState.fileLabel = cache.fileLabel || '';
            _recontactState.savedAt = cache.savedAt;
            _recontactState.savedByUsername = cache.savedByUsername || '';
            // Refrescar tags Callbell antes de renderizar (puede haber cambios desde otro admin).
            await _recontactHydrateCallbellTags(_recontactState.items);
            // Cargar análisis previo (si hay) para poder mostrar mejoras archivo-a-archivo.
            try {
                const prev = await _recontactLoadPreviousAnalysis();
                if (prev && Array.isArray(prev.items)) {
                    _recontactState.previousItems = prev.items;
                    _recontactState.previousSavedAt = prev.savedAt || null;
                }
            } catch (_) {}
            c.innerHTML = _renderRecontactUserSearch() + _renderRecontactDashboard(_recontactState.summary, _recontactState.items) + _renderRecontactDailyProgress();
            _wireRecontactFilters();
            _wireRecontactSearch();
            _wireRecontactDailyProgress();
            return;
        }
    }).catch(e => {
        try { document.getElementById('recontactCacheProbe')?.remove(); } catch (_) {}
        console.warn('[recontact] loadCache fail', e);
    });
}

// Hidrata cada item con su estado de tags Callbell (etiqueta/wa/respuesta).
async function _recontactHydrateCallbellTags(items) {
    if (!Array.isArray(items) || items.length === 0) return;
    try {
        const usernames = items.map(it => it.username).filter(Boolean);
        // chunk por las dudas
        const chunkSize = 5000;
        const tagMap = {};
        for (let i = 0; i < usernames.length; i += chunkSize) {
            const chunk = usernames.slice(i, i + chunkSize);
            const r = await authFetch('/api/admin/callbell/tags-by-usernames', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ usernames: chunk })
            });
            if (!r.ok) continue;
            const j = await r.json();
            Object.assign(tagMap, j.tags || {});
        }
        for (const it of items) {
            const norm = String(it.username || '').toLowerCase().replace(/[^a-z0-9]/g, '');
            const t = tagMap[norm];
            if (t) {
                it.cbEtiqueta = !!(t.etiqueta && t.etiqueta.tagged);
                it.cbWa       = !!(t.wa && t.wa.tagged);
                it.cbResp     = (t.respuesta && t.respuesta.status) || null; // 'instalo' | 'no_contesto' | null
                it.cbConvertedAt = t.convertedAt || null;
                it.cbHadAppAtFirstTag = !!t.hadAppAtFirstTag;
            } else {
                it.cbEtiqueta = false;
                it.cbWa = false;
                it.cbResp = null;
                it.cbConvertedAt = null;
                it.cbHadAppAtFirstTag = false;
            }
        }
    } catch (e) {
        console.warn('[recontact] hydrate Callbell tags fail', e);
    }
}

// Pending changes — tildes que el usuario hizo pero todavía no están
// confirmadas en el server (porque se cayó la red o porque manualmente
// quiere mandar todos juntos). El botón "💾 Guardar cambios" los flushea.
window._recontactPendingTags = window._recontactPendingTags || {};

// Aplica el cambio LOCAL al item (state en memoria) y marca como pending.
// El auto-save al server se dispara en background; si falla, el item queda
// en pending y el botón "Guardar cambios" muestra el contador para reintentar.
function _recontactApplyTagChangeLocal(username, action, newSet) {
    const it = (_recontactState.items || []).find(x => x.username === username);
    if (!it) return;
    if (action === 'etiqueta') it.cbEtiqueta = newSet;
    else if (action === 'wa') it.cbWa = newSet;
    else if (action === 'instalo') it.cbResp = newSet ? 'instalo' : null;
    else if (action === 'no_contesto') it.cbResp = newSet ? 'no_contesto' : null;
    if (!window._recontactPendingTags[username]) window._recontactPendingTags[username] = {};
    window._recontactPendingTags[username][action] = newSet;
    _updateRecontactSaveButton();
}

// Saca un tag del pending list (luego de save exitoso).
function _recontactClearPending(username, action) {
    if (window._recontactPendingTags[username]) {
        delete window._recontactPendingTags[username][action];
        if (Object.keys(window._recontactPendingTags[username]).length === 0) {
            delete window._recontactPendingTags[username];
        }
    }
    _updateRecontactSaveButton();
}

// Cuenta los cambios pendientes y refresca el banner "Guardar tildes".
function _updateRecontactSaveButton() {
    const btn = document.getElementById('recontactSaveAllBtn');
    const banner = document.getElementById('recontactSaveBanner');
    const status = document.getElementById('recontactSaveStatus');
    if (!btn) return;
    let count = 0;
    for (const u in window._recontactPendingTags) {
        count += Object.keys(window._recontactPendingTags[u]).length;
    }
    if (count === 0) {
        // Todo guardado — banner verde, botón verde apagado.
        btn.textContent = '✅ TODO GUARDADO';
        btn.style.background = 'linear-gradient(135deg,#25d366,#128c4f)';
        btn.style.boxShadow = '0 4px 14px rgba(37,211,102,0.35)';
        btn.style.cursor = 'default';
        if (banner) banner.style.borderBottomColor = 'rgba(37,211,102,0.40)';
        if (status) status.textContent = 'Todos los tildes están sincronizados con el server.';
    } else {
        // Hay pendientes — botón rojo intenso con count.
        btn.textContent = '💾 GUARDAR ' + count + ' CAMBIO' + (count === 1 ? '' : 'S');
        btn.style.background = 'linear-gradient(135deg,#ff5050,#aa1a1a)';
        btn.style.boxShadow = '0 4px 14px rgba(255,80,80,0.45)';
        btn.style.cursor = 'pointer';
        if (banner) banner.style.borderBottomColor = 'rgba(255,80,80,0.50)';
        if (status) status.innerHTML = '<strong style="color:#ff8080;">Hay ' + count + ' cambio' + (count === 1 ? '' : 's') + ' sin confirmar al server.</strong> Tocá el botón para guardar todo.';
    }
}

// Envía un cambio individual al server. Si falla, lo deja en pending para
// que el botón "Guardar cambios" lo reintente.
async function _recontactPushTag(username, action, newSet, bucket, tier) {
    try {
        const r = await authFetch('/api/admin/callbell/tag', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                username, action, set: newSet,
                bucket: bucket || '',
                tier: tier || '',
                analysisLabel: (_recontactState && _recontactState.fileLabel) || ''
            })
        });
        if (!r.ok) {
            let errMsg = 'HTTP ' + r.status;
            try { const j = await r.json(); if (j && j.error) errMsg = j.error; } catch (_) {}
            console.warn('[callbell] push fail:', errMsg, username, action);
            // Mostrar toast solo si NO es un 401 (reauthRequired) o errores comunes
            if (r.status !== 401) {
                showToast('⚠ No se pudo guardar tilde de ' + username + ': ' + errMsg + ' — usá "GUARDAR TILDES" para reintentar', 'error');
            }
            return false;
        }
        _recontactClearPending(username, action);
        return true;
    } catch (e) {
        console.warn('[callbell] push exception:', e);
        showToast('⚠ Sin conexión al server — el tilde quedó pendiente. Tocá GUARDAR TILDES cuando vuelva la red.', 'error');
        return false;
    }
}

// Botón "💾 Guardar cambios": flushea TODOS los pending al server en paralelo.
// Los que fallan quedan en pending para reintentar.
async function recontactSaveAllTags() {
    const pending = Object.entries(window._recontactPendingTags || {});
    if (pending.length === 0) {
        showToast('No hay cambios por guardar', 'info');
        return;
    }
    const btn = document.getElementById('recontactSaveAllBtn');
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Guardando…'; }

    const tasks = [];
    for (const [username, actions] of pending) {
        const it = (_recontactState.items || []).find(x => x.username === username);
        const bucket = it ? (it.bucket || '') : '';
        const tier = it ? (it.tier || '') : '';
        for (const action in actions) {
            const newSet = actions[action];
            tasks.push(_recontactPushTag(username, action, newSet, bucket, tier));
        }
    }
    const results = await Promise.all(tasks);
    const okCount = results.filter(Boolean).length;
    const failCount = results.length - okCount;
    if (failCount === 0) {
        showToast('✅ ' + okCount + ' cambios guardados', 'success');
    } else {
        showToast('⚠ ' + okCount + ' guardados · ' + failCount + ' con error (probá de nuevo)', 'error');
    }
    _updateRecontactSaveButton();
}

// Handler único delegado para checkboxes Callbell — se asigna a document.body
// una sola vez. Usar document.body en lugar de un container que se reemplaza
// con innerHTML evita duplicados de listener cuando el dashboard re-renderiza.
let _cbCallbellHandlerWired = false;
function _wireRecontactCallbellCheckboxes() {
    if (_cbCallbellHandlerWired) return;
    _cbCallbellHandlerWired = true;
    document.body.addEventListener('change', (e) => {
        const t = e.target;
        if (!t || !t.classList || !t.classList.contains('cb-callbell-toggle')) return;
        const username = t.dataset.user || '';
        const action = t.dataset.action || '';
        const newSet = !!t.checked;
        if (!username || !action) return;
        // 1) Aplicar local + marcar pending + actualizar botón.
        _recontactApplyTagChangeLocal(username, action, newSet);
        // 2) Si tildaste "instalo" desmarcar "no_contesto" en local (mutuamente excluyentes).
        const it = (_recontactState.items || []).find(x => x.username === username);
        if (it) {
            if (action === 'instalo' && newSet && it.cbResp === 'no_contesto') {
                _recontactApplyTagChangeLocal(username, 'no_contesto', false);
            } else if (action === 'no_contesto' && newSet && it.cbResp === 'instalo') {
                _recontactApplyTagChangeLocal(username, 'instalo', false);
            }
        }
        // 3) Disparar auto-save en background (no bloquea UI).
        const bucket = it ? (it.bucket || '') : '';
        const tier = it ? (it.tier || '') : '';
        _recontactPushTag(username, action, newSet, bucket, tier).then(ok => {
            if (ok) _updateRecontactSaveButton();
        });
        // 4) Re-render para reflejar mutual exclusion visualmente.
        const cont = document.getElementById('recontactContent');
        if (cont) {
            cont.innerHTML = _renderRecontactDashboard(_recontactState.summary, _recontactState.items);
            _wireRecontactFilters();
        }
    });
}

function _renderRecontactUploader() {
    let html = '';
    html += '<div id="recontactDropZone" ondragover="_recontactDragOver(event)" ondragleave="_recontactDragLeave(event)" ondrop="_recontactDrop(event)" style="background:rgba(0,212,255,0.04);border:2px dashed rgba(0,212,255,0.40);border-radius:14px;padding:34px 24px;text-align:center;transition:all 0.2s ease;">';
    html += '  <div style="font-size:54px;margin-bottom:10px;">📤</div>';
    html += '  <h3 style="color:#00d4ff;margin:0 0 8px;font-size:20px;">Subí el .xlsx con la lista a recontactar</h3>';
    html += '  <p style="color:#bbb;font-size:13px;line-height:1.6;margin:0 0 16px;max-width:640px;margin-left:auto;margin-right:auto;">Detecta automáticamente columnas <strong style="color:#fff;">Type</strong> · <strong style="color:#fff;">Amount</strong> · <strong style="color:#fff;">User</strong> y agrega por usuario: <strong style="color:#25d366;">cargas</strong> (deposit), <strong style="color:#ff5050;">retiros</strong> (withdraw) y <strong style="color:#ffd700;">bonos</strong> (individual_bonus). Por cada uno te dice: tier, días sin cargar, app/notifs, teléfono, <strong style="color:#ffd700;">estrategia</strong>, <strong style="color:#25d366;">bono recomendado</strong> y mensaje WhatsApp.</p>';
    html += '  <p style="color:#888;font-size:11.5px;margin:0 0 16px;">💡 Podés también arrastrar y soltar el archivo acá.</p>';
    html += '  <input type="file" id="recontactFile" accept=".xlsx,.xls" onchange="_recontactFilePicked()" style="margin:0 auto 6px;display:block;padding:11px;border-radius:8px;border:1px solid rgba(255,255,255,0.18);background:rgba(0,0,0,0.45);color:#fff;font-size:13px;width:100%;max-width:380px;box-sizing:border-box;">';
    html += '  <div id="recontactFileInfo" style="color:#aaa;font-size:11.5px;margin:8px 0;min-height:18px;"></div>';
    html += '  <button type="button" onclick="recontactAnalyze()" id="recontactAnalyzeBtn" style="margin-top:8px;padding:13px 26px;font-size:14px;font-weight:800;background:linear-gradient(135deg,#00d4ff,#0080ff);border:none;color:#000;border-radius:9px;cursor:pointer;letter-spacing:0.5px;box-shadow:0 4px 14px rgba(0,212,255,0.35);">🔍 ANALIZAR LISTA</button>';
    html += '  <div id="recontactProgress" style="margin-top:14px;color:#aaa;font-size:12px;display:none;"></div>';
    html += '</div>';
    // Tip secundario debajo del drop zone.
    html += '<div style="background:rgba(212,175,55,0.04);border:1px solid rgba(212,175,55,0.20);border-radius:10px;padding:10px 14px;margin-top:12px;color:#bbb;font-size:11.5px;line-height:1.6;">';
    html += '  💡 <strong style="color:#ffd700;">Tip:</strong> hasta 25MB / 50.000 usernames, multi-hoja. Si el header dice <code style="background:rgba(0,0,0,0.4);padding:1px 5px;border-radius:3px;color:#00d4ff;">Type</code> + <code style="background:rgba(0,0,0,0.4);padding:1px 5px;border-radius:3px;color:#00d4ff;">Amount</code> + <code style="background:rgba(0,0,0,0.4);padding:1px 5px;border-radius:3px;color:#00d4ff;">User</code> agrupa los movimientos por usuario. Si no hay header, toma la primera columna como username.';
    html += '</div>';
    return html;
}

function _recontactDragOver(e) {
    e.preventDefault();
    e.stopPropagation();
    const z = document.getElementById('recontactDropZone');
    if (z) {
        z.style.background = 'rgba(0,212,255,0.12)';
        z.style.borderColor = '#00d4ff';
    }
}
function _recontactDragLeave(e) {
    e.preventDefault();
    e.stopPropagation();
    const z = document.getElementById('recontactDropZone');
    if (z) {
        z.style.background = 'rgba(0,212,255,0.04)';
        z.style.borderColor = 'rgba(0,212,255,0.40)';
    }
}
function _recontactDrop(e) {
    e.preventDefault();
    e.stopPropagation();
    _recontactDragLeave(e);
    const dt = e.dataTransfer;
    if (!dt || !dt.files || dt.files.length === 0) return;
    const f = dt.files[0];
    if (!f.name.match(/\.(xlsx|xls)$/i)) {
        showToast('Sólo .xlsx o .xls', 'error');
        return;
    }
    const inp = document.getElementById('recontactFile');
    if (inp) {
        // Asignar el archivo al input para que recontactAnalyze lo lea.
        const dtTrans = new DataTransfer();
        dtTrans.items.add(f);
        inp.files = dtTrans.files;
        _recontactFilePicked();
    }
}

function _recontactFilePicked() {
    const inp = document.getElementById('recontactFile');
    const info = document.getElementById('recontactFileInfo');
    if (!inp || !info) return;
    const f = inp.files && inp.files[0];
    if (!f) { info.textContent = ''; return; }
    const sizeKb = (f.size / 1024).toFixed(1);
    info.innerHTML = '📄 <strong style="color:#fff;">' + escapeHtml(f.name) + '</strong> · ' + sizeKb + ' KB';
}

// Parsea el .xlsx EN EL NAVEGADOR usando SheetJS, agrega por usuario,
// y manda al server sólo el JSON resultante (mucho más liviano que el binario).
// Esto evita timeouts/502 con archivos grandes.
async function _recontactParseLocally(file, onProgress) {
    if (typeof XLSX === 'undefined') {
        throw new Error('Librería XLSX no cargada (probá refrescar la página)');
    }
    onProgress && onProgress('📖 Leyendo archivo…');
    const buf = await file.arrayBuffer();
    onProgress && onProgress('🔍 Parseando hojas…');
    const wb = XLSX.read(buf, { type: 'array', cellDates: false });

    const HEADER_TYPE = new Set(['type', 'tipo', 'movimiento']);
    const HEADER_AMOUNT = new Set(['amount', 'monto', 'cantidad', 'importe']);
    const HEADER_USER = new Set(['user', 'username', 'usuario']);
    const TYPE_DEPOSIT = new Set(['deposit', 'deposito', 'depósito', 'carga']);
    const TYPE_WITHDRAW = new Set(['withdraw', 'withdrawal', 'retiro', 'extraccion', 'extracción']);
    const TYPE_BONUS = new Set(['individual_bonus', 'bonus', 'bonificacion', 'bonificación', 'bono']);

    const agg = new Map();
    let totalRows = 0;

    for (const sheetName of wb.SheetNames) {
        const sheet = wb.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, blankrows: false, defval: null });
        if (!rows || rows.length === 0) continue;

        let colType = -1, colAmount = -1, colUser = -1;
        const firstRow = Array.isArray(rows[0]) ? rows[0] : [];
        for (let i = 0; i < firstRow.length; i++) {
            const h = String(firstRow[i] == null ? '' : firstRow[i]).trim().toLowerCase();
            if (HEADER_TYPE.has(h)) colType = i;
            else if (HEADER_AMOUNT.has(h)) colAmount = i;
            else if (HEADER_USER.has(h)) colUser = i;
        }
        const hasHeader = (colUser !== -1) || (colType !== -1) || (colAmount !== -1);
        const userColIdx = (colUser !== -1) ? colUser : 0;
        const startRow = hasHeader ? 1 : 0;

        for (let r = startRow; r < rows.length; r++) {
            const row = rows[r];
            if (!Array.isArray(row) || row.length === 0) continue;
            const userCell = row[userColIdx];
            if (userCell == null) continue;
            const v = String(userCell).trim();
            if (!v) continue;
            const lower = v.toLowerCase();
            if (!hasHeader && (lower === 'username' || lower === 'usuario' || lower === 'user')) continue;
            const norm = lower.replace(/[^a-z0-9]/g, '');
            if (!norm) continue;

            let a = agg.get(norm);
            if (!a) {
                a = {
                    username: v,
                    sumDeposits: 0, sumWithdraws: 0, sumBonuses: 0,
                    countDeposits: 0, countWithdraws: 0, countBonuses: 0
                };
                agg.set(norm, a);
            }

            if (colType !== -1 && colAmount !== -1) {
                const tRaw = String(row[colType] == null ? '' : row[colType]).trim().toLowerCase();
                const amtRaw = row[colAmount];
                const amt = (amtRaw == null || amtRaw === '') ? 0 : Number(String(amtRaw).replace(/[^\d.\-]/g, ''));
                if (Number.isFinite(amt) && amt > 0) {
                    if (TYPE_DEPOSIT.has(tRaw))      { a.sumDeposits  += amt; a.countDeposits++; }
                    else if (TYPE_WITHDRAW.has(tRaw)){ a.sumWithdraws += amt; a.countWithdraws++; }
                    else if (TYPE_BONUS.has(tRaw))   { a.sumBonuses   += amt; a.countBonuses++; }
                }
            }
            totalRows++;
        }
    }

    const users = Array.from(agg.values());
    return { users, totalRows };
}

async function recontactAnalyze() {
    const inp = document.getElementById('recontactFile');
    const btn = document.getElementById('recontactAnalyzeBtn');
    const progress = document.getElementById('recontactProgress');
    const file = inp && inp.files && inp.files[0];
    if (!file) { showToast('Subí un archivo .xlsx primero', 'error'); return; }
    if (file.size > 50 * 1024 * 1024) { showToast('Archivo muy grande (>50MB)', 'error'); return; }
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Procesando…'; }
    const setProg = (msg) => {
        if (progress) { progress.style.display = 'block'; progress.textContent = msg; }
    };
    const restoreBtn = () => {
        if (btn) { btn.disabled = false; btn.textContent = '🔍 ANALIZAR LISTA'; }
        if (progress) { progress.style.display = 'none'; }
    };
    try {
        // 1) Parsear el .xlsx en el navegador (ahorra ancho de banda + memoria del server)
        setProg('📖 Parseando ' + (file.size / 1024 / 1024).toFixed(1) + ' MB localmente…');
        const parsed = await _recontactParseLocally(file, setProg);
        if (!parsed.users || parsed.users.length === 0) {
            showToast('❌ No encontré usernames en el archivo', 'error');
            restoreBtn();
            return;
        }
        if (parsed.users.length > 50000) {
            showToast('❌ Demasiados usernames (' + parsed.users.length + ', máx 50.000). Partí el archivo en dos.', 'error');
            restoreBtn();
            return;
        }

        // 2) Enviar al server SÓLO el JSON agregado (típicamente <1MB)
        setProg('📡 Enviando ' + parsed.users.length.toLocaleString('es-AR') + ' usuarios al server…');
        const r = await authFetch('/api/admin/recontact/analyze', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ version: 2, users: parsed.users, totalRows: parsed.totalRows })
        });
        let raw = '';
        try { raw = await r.text(); } catch (_) { raw = ''; }
        if (!raw) {
            showToast('❌ Server respondió vacío (status ' + r.status + ')', 'error');
            restoreBtn();
            return;
        }
        let j;
        try { j = JSON.parse(raw); }
        catch (_) {
            const peek = raw.slice(0, 200).replace(/<[^>]+>/g, ' ').trim();
            showToast('❌ Respuesta inesperada (status ' + r.status + '): ' + (peek || 'sin texto'), 'error');
            restoreBtn();
            return;
        }
        if (!r.ok || !j.success) {
            showToast('❌ ' + (j.error || 'Error ' + r.status), 'error');
            restoreBtn();
            return;
        }
        _recontactState.items = j.items || [];
        _recontactState.summary = j.summary || {};
        _recontactState.fileLabel = (file && file.name) || '';
        _recontactState.savedAt = Date.now();
        // Hidratar tags Callbell desde el server (etiqueta/wa/respuesta)
        await _recontactHydrateCallbellTags(_recontactState.items);
        // Guardar en cache IDB (7 días) + push al historial localStorage.
        // El save se hace en background — no bloqueamos la UI.
        _recontactSaveCache(_recontactState.items, _recontactState.summary, _recontactState.fileLabel)
            .catch(e => console.warn('[recontact] save fail', e));
        _recontactPushHistorySnapshot(_recontactState.items, _recontactState.summary, _recontactState.fileLabel);
        loadRecontactSection();
        showToast('✅ ' + (j.summary.totalAnalyzed || 0) + ' usuarios analizados (queda guardado por 7 días)', 'success');
    } catch (e) {
        showToast('Error: ' + (e.message || e), 'error');
        restoreBtn();
    }
}

function recontactReset() {
    _recontactState = { items: null, summary: null, file: null, fileLabel: '', savedAt: null };
    _recontactClearCache().catch(() => {});
    window._recontactFilters = { tier: 'all', bucket: 'all', appStatus: 'all', line: 'all' };
    loadRecontactSection();
}

window._recontactFilters = window._recontactFilters || { tier: 'all', bucket: 'all', appStatus: 'all', line: 'all' };

function _recontactBuildLineOptions(items) {
    const map = new Map();
    let noLine = 0;
    for (const it of items) {
        if (!it.team && !it.linePhone) { noLine++; continue; }
        const key = (it.team || '') + '||' + (it.linePhone || '');
        const cur = map.get(key);
        if (cur) cur.count++;
        else map.set(key, { team: it.team || '', linePhone: it.linePhone || '', count: 1 });
    }
    const opts = [];
    const sorted = Array.from(map.entries()).sort((a, b) => b[1].count - a[1].count);
    for (const [key, v] of sorted) {
        const lbl = (v.team || '(sin equipo)') + (v.linePhone ? ' · ' + v.linePhone : '') + ' (' + v.count + ')';
        opts.push({ key, label: lbl });
    }
    if (noLine > 0) opts.push({ key: 'no-line', label: '⚠ Sin línea asignada (' + noLine + ')' });
    return opts;
}

function _bucketLabelForExport(b) {
    return ({ calientes: '0-10 dias', enRiesgo: '10-20 dias', perdidos: '20-30 dias', inactivos: '+30 dias' })[b] || (b || '');
}

function _csvEscape(v) {
    const s = (v == null ? '' : String(v));
    return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}

function _downloadCsvLocal(filename, lines) {
    const csv = '﻿' + lines.join('\r\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { try { URL.revokeObjectURL(url); a.remove(); } catch (_) {} }, 1500);
}

function _recontactCurrentSuffix() {
    const f = window._recontactFilters || {};
    const parts = [];
    if (f.bucket && f.bucket !== 'all') parts.push(f.bucket);
    if (f.tier && f.tier !== 'all') parts.push(f.tier);
    if (f.appStatus && f.appStatus !== 'all') parts.push(f.appStatus);
    if (f.line && f.line !== 'all') parts.push('linea');
    return parts.length ? '-' + parts.join('-') : '';
}

// Helper: el "phone" para WhatsApp es preferentemente el del cliente (it.phone),
// pero si el cliente no está registrado solo tenemos el de la línea asignada
// del equipo (it.linePhone). Si tampoco hay nada, queda vacío.
function _recontactBestPhone(it) {
    return it.phone || it.linePhone || '';
}

// Lista SIMPLE: name + phone + linea + equipo. Respeta los filtros activos.
function recontactDownloadSimple() {
    const items = _filterRecontactItems(_recontactState.items || [], window._recontactFilters || {});
    if (!items.length) { showToast('Sin items con los filtros actuales', 'info'); return; }
    const lines = ['name,phone,linea,equipo'];
    let exported = 0, sinNada = 0;
    for (const it of items) {
        const phone = _recontactBestPhone(it);
        const linea = it.linePhone || '';
        const equipo = it.team || '';
        if (!phone && !linea && !equipo) { sinNada++; }
        lines.push([
            _csvEscape(it.username),
            _csvEscape(phone),
            _csvEscape(linea),
            _csvEscape(equipo)
        ].join(','));
        exported++;
    }
    _downloadCsvLocal('recontactacion-simple' + _recontactCurrentSuffix() + '-' + new Date().toISOString().slice(0,10) + '.csv', lines);
    const noteParts = ['✅ ' + exported + ' filas exportadas'];
    if (sinNada > 0) noteParts.push('(' + sinNada + ' sin teléfono ni línea)');
    showToast(noteParts.join(' '), 'success');
}

// Lista DETALLADA: name, phone, linea, equipo, mensaje, rango, carga, descarga, diferencia.
function recontactDownloadDetailed() {
    const items = _filterRecontactItems(_recontactState.items || [], window._recontactFilters || {});
    if (!items.length) { showToast('Sin items con los filtros actuales', 'info'); return; }
    const lines = ['name,phone,linea,equipo,mensaje,rango,carga,descarga,diferencia,bono_sugerido,tiene_app,tiene_notifs'];
    let exported = 0;
    for (const it of items) {
        const phone = _recontactBestPhone(it);
        lines.push([
            _csvEscape(it.username),
            _csvEscape(phone),
            _csvEscape(it.linePhone || ''),
            _csvEscape(it.team || ''),
            _csvEscape(it.suggestedMessage || ''),
            _csvEscape(_bucketLabelForExport(it.bucket)),
            _csvEscape(Number(it.fileDeposits || 0)),
            _csvEscape(Number(it.fileWithdraws || 0)),
            _csvEscape(Number(it.fileNet || 0)),
            _csvEscape(Number(it.suggestedBonus || 0)),
            _csvEscape(it.hasApp ? 'Si' : 'No'),
            _csvEscape(it.hasNotifs ? 'Si' : 'No')
        ].join(','));
        exported++;
    }
    _downloadCsvLocal('recontactacion-detallado' + _recontactCurrentSuffix() + '-' + new Date().toISOString().slice(0,10) + '.csv', lines);
    showToast('✅ ' + exported + ' filas exportadas', 'success');
}

// XLSX con UNA hoja por equipo (los items se agrupan por it.team) — respeta
// filtros activos. Sirve cuando seleccionás (por ej.) "En riesgo" en el
// panorama y querés ver/distribuir el corte separado por equipo en un solo
// archivo. Si no hay equipo, va a una hoja "(Sin equipo)".
function recontactDownloadXlsxByTeam() {
    if (typeof XLSX === 'undefined') { showToast('Librería XLSX no cargada — refrescá la página', 'error'); return; }
    const items = _filterRecontactItems(_recontactState.items || [], window._recontactFilters || {});
    if (!items.length) { showToast('Sin items con los filtros actuales', 'info'); return; }

    // Agrupar por equipo
    const byTeam = new Map();
    for (const it of items) {
        const t = it.team || '(Sin equipo)';
        if (!byTeam.has(t)) byTeam.set(t, []);
        byTeam.get(t).push(it);
    }
    // Ordenar equipos por cantidad descendente
    const teams = Array.from(byTeam.entries()).sort((a, b) => b[1].length - a[1].length);

    const wb = XLSX.utils.book_new();
    const fmt = n => Number(n || 0);

    // Hoja Resumen primera
    const resumen = [
        ['RECONTACTACIÓN — Resumen por equipo'],
        ['Generado', new Date().toLocaleString('es-AR')],
        ['Filtros activos', _recontactDescribeFilters()],
        [''],
        ['Equipo', 'Cantidad', 'Con app', 'Push directo', 'Sin app', 'Sin línea', '$ Cargas (arch)', '$ Retiros (arch)', '$ Neto']
    ];
    let totCount = 0, totConApp = 0, totPush = 0, totSinApp = 0, totSinLinea = 0;
    let totCargas = 0, totRetiros = 0, totNeto = 0;
    for (const [team, list] of teams) {
        let conApp = 0, push = 0, sinApp = 0, sinLinea = 0;
        let cargas = 0, retiros = 0, neto = 0;
        for (const it of list) {
            if (it.hasApp) conApp++;
            if (it.hasApp && it.hasNotifs) push++;
            if (!it.hasApp) sinApp++;
            if (!it.team && !it.linePhone) sinLinea++;
            cargas += Number(it.fileDeposits || 0);
            retiros += Number(it.fileWithdraws || 0);
            neto += Number(it.fileNet || 0);
        }
        resumen.push([team, list.length, conApp, push, sinApp, sinLinea, cargas, retiros, neto]);
        totCount += list.length; totConApp += conApp; totPush += push; totSinApp += sinApp; totSinLinea += sinLinea;
        totCargas += cargas; totRetiros += retiros; totNeto += neto;
    }
    resumen.push(['TOTAL', totCount, totConApp, totPush, totSinApp, totSinLinea, totCargas, totRetiros, totNeto]);
    const resSheet = XLSX.utils.aoa_to_sheet(resumen);
    resSheet['!cols'] = [{ wch: 26 }, { wch: 10 }, { wch: 10 }, { wch: 14 }, { wch: 10 }, { wch: 12 }, { wch: 18 }, { wch: 18 }, { wch: 16 }];
    XLSX.utils.book_append_sheet(wb, resSheet, '📋 Resumen');

    // Una hoja por equipo
    for (const [team, list] of teams) {
        const headers = ['name', 'phone', 'linea', 'equipo', 'mensaje', 'rango', 'carga', 'descarga', 'diferencia', 'bono_sugerido', 'tiene_app', 'tiene_notifs', 'tier'];
        const data = [headers];
        for (const it of list) {
            data.push([
                it.username || '',
                _recontactBestPhone(it),
                it.linePhone || '',
                it.team || '',
                it.suggestedMessage || '',
                _bucketLabelForExport(it.bucket),
                fmt(it.fileDeposits),
                fmt(it.fileWithdraws),
                fmt(it.fileNet),
                fmt(it.suggestedBonus),
                it.hasApp ? 'Si' : 'No',
                it.hasNotifs ? 'Si' : 'No',
                it.tier || ''
            ]);
        }
        const sheet = XLSX.utils.aoa_to_sheet(data);
        sheet['!cols'] = [
            { wch: 22 }, { wch: 18 }, { wch: 18 }, { wch: 22 }, { wch: 50 },
            { wch: 12 }, { wch: 12 }, { wch: 12 }, { wch: 12 }, { wch: 12 },
            { wch: 9 },  { wch: 11 }, { wch: 10 }
        ];
        // Truncar nombre de hoja a 31 chars (límite Excel) y sanitizar
        const safeName = String(team).replace(/[\\/?*[\]:]/g, '_').slice(0, 31) || 'Equipo';
        XLSX.utils.book_append_sheet(wb, sheet, safeName);
    }

    const buf = XLSX.write(wb, { type: 'array', bookType: 'xlsx' });
    const blob = new Blob([buf], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'recontactacion-equipos' + _recontactCurrentSuffix() + '-' + new Date().toISOString().slice(0, 10) + '.xlsx';
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { try { URL.revokeObjectURL(url); a.remove(); } catch (_) {} }, 1500);
    showToast('✅ XLSX descargado · ' + teams.length + ' hoja' + (teams.length === 1 ? '' : 's') + ' (' + items.length + ' filas)', 'success');
}

// ============================================
// 📱 USUARIOS CON APP — conteo real sobre toda la base
// ============================================
async function loadAppUsers() {
    const c = document.getElementById('appUsersContent');
    if (!c) return;
    c.innerHTML = '<div class="empty-state" style="padding:30px;text-align:center;color:#aaa;">⏳ Consultando base…</div>';
    try {
        const [statsR, histR, cbR] = await Promise.all([
            authFetch('/api/admin/app-users/stats'),
            authFetch('/api/admin/app-users/history?days=60'),
            authFetch('/api/admin/callbell/report?days=30')
        ]);
        if (!statsR.ok) {
            const j = await statsR.json().catch(() => ({}));
            c.innerHTML = '<div style="padding:20px;color:#ff8080;">❌ ' + (j.error || ('Error ' + statsR.status)) + '</div>';
            return;
        }
        const data = await statsR.json();
        const histJson = histR.ok ? await histR.json() : { history: [] };
        const cbJson = cbR.ok ? await cbR.json() : { totals: {}, daily: [] };
        data._history = (histJson && histJson.history) || [];
        data._callbell = cbJson || {};
        c.innerHTML = _renderAppUsersDashboard(data);
    } catch (e) {
        c.innerHTML = '<div style="padding:20px;color:#ff8080;">❌ ' + (e.message || e) + '</div>';
    }
}

function _renderAppUsersDashboard(data) {
    const fmt = n => Number(n || 0).toLocaleString('es-AR');
    const t = data.totals || {};
    const total = t.totalUsers || 0;
    const pct = (n) => total > 0 ? ((n / total) * 100).toFixed(1) + '%' : '0%';
    let html = '';

    // KPIs grandes
    html += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;margin-bottom:14px;">';
    html += _kpiCardLite('Total registrados', fmt(total), '#fff', 'usuarios en la base');
    html += _kpiCardLite('Con app instalada', fmt(t.withApp), '#7cffb3', pct(t.withApp) + ' de la base');
    html += _kpiCardLite('Con notifs activas', fmt(t.withNotifs), '#25d366', pct(t.withNotifs) + ' de la base');
    html += _kpiCardLite('Push directo (app+notifs)', fmt(t.withBoth), '#00d4ff', pct(t.withBoth) + ' de la base');
    html += _kpiCardLite('Con app sin notifs', fmt(t.withAppNoNotifs), '#ffaa44', 'reactivar');
    html += _kpiCardLite('Sin app', fmt(t.sinApp), '#888', pct(t.sinApp) + ' (WhatsApp)');
    html += '</div>';

    html += '<div style="color:#aaa;font-size:11px;margin-bottom:10px;">Generado: ' + new Date(data.generatedAt).toLocaleString('es-AR') + '. Criterio: token con <code style="color:#00d4ff;">context=standalone</code> (PWA real instalada).</div>';

    // === Atribución Callbell ===
    const cb = data._callbell || {};
    const cbTotals = cb.totals || {};
    const cbAttrib = data.callbellAttribution || {};
    if ((cbTotals.totalTagged || 0) > 0 || (cbAttrib.total || 0) > 0) {
        html += '<details open style="background:rgba(155,48,255,0.05);border:1px solid rgba(155,48,255,0.30);border-radius:10px;padding:0;margin-bottom:14px;overflow:hidden;">';
        html += '  <summary style="cursor:pointer;padding:10px 14px;background:rgba(155,48,255,0.08);list-style:none;display:flex;justify-content:space-between;align-items:center;">';
        html += '    <span style="color:#9b30ff;font-weight:800;font-size:13px;letter-spacing:0.5px;">📞 ATRIBUCIÓN CALLBELL — etiqueta WhatsApp → instalación de app</span>';
        html += '    <span style="color:#888;font-size:10.5px;">tocá para abrir/cerrar ▾</span>';
        html += '  </summary>';
        html += '  <div style="padding:12px 14px;">';

        // KPIs Callbell
        html += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-bottom:12px;">';
        html += _kpiCardLite('🏷 Total etiquetados', fmt(cbTotals.totalTagged || 0), '#9b30ff', 'Marcados en Callbell');
        html += _kpiCardLite('📤 WA enviado', fmt(cbTotals.totalWA || 0), '#25d366', 'Mensaje mandado');
        html += _kpiCardLite('✅ Instaló (manual)', fmt(cbTotals.totalInstalo || 0), '#7cffb3', 'Confirmado por agente');
        html += _kpiCardLite('✕ No contestó', fmt(cbTotals.totalNoContesto || 0), '#ff8080', 'Sin respuesta');
        html += _kpiCardLite('📱 Convirtieron a app', fmt(cbAttrib.total || 0), '#00d4ff', (cbTotals.conversionRatePct || 0) + '% de etiquetados');
        html += '</div>';

        // Tabla diaria
        const daily = (cb.daily || []).slice().sort((a, b) => (b.dayKey || '').localeCompare(a.dayKey || ''));
        if (daily.length > 0) {
            html += '<div style="color:#aaa;font-size:11px;margin-bottom:6px;">Reporte diario · últimos ' + (cb.windowDays || 30) + ' días</div>';
            html += '<div style="overflow-x:auto;max-height:300px;overflow-y:auto;">';
            html += '<table style="width:100%;border-collapse:collapse;font-size:11.5px;min-width:540px;">';
            html += '  <thead><tr style="background:rgba(255,255,255,0.04);position:sticky;top:0;">';
            html += '    <th style="text-align:left;padding:6px 10px;color:#aaa;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">Día</th>';
            html += '    <th style="text-align:right;padding:6px 10px;color:#9b30ff;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">🏷 Etiq</th>';
            html += '    <th style="text-align:right;padding:6px 10px;color:#25d366;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">📤 WA</th>';
            html += '    <th style="text-align:right;padding:6px 10px;color:#7cffb3;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">✅ Instaló</th>';
            html += '    <th style="text-align:right;padding:6px 10px;color:#ff8080;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">✕ NoCont</th>';
            html += '    <th style="text-align:right;padding:6px 10px;color:#00d4ff;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">📱 Auto</th>';
            html += '  </tr></thead><tbody>';
            for (const d of daily) {
                html += '<tr style="border-bottom:1px solid rgba(255,255,255,0.04);">';
                html += '  <td style="padding:5px 10px;color:#fff;font-weight:600;">' + escapeHtml(d.dayKey || '') + '</td>';
                html += '  <td style="padding:5px 10px;text-align:right;color:#9b30ff;">' + fmt(d.etiquetados || 0) + '</td>';
                html += '  <td style="padding:5px 10px;text-align:right;color:#25d366;">' + fmt(d.wa || 0) + '</td>';
                html += '  <td style="padding:5px 10px;text-align:right;color:#7cffb3;font-weight:700;">' + fmt(d.instalo || 0) + '</td>';
                html += '  <td style="padding:5px 10px;text-align:right;color:#ff8080;">' + fmt(d.noContesto || 0) + '</td>';
                html += '  <td style="padding:5px 10px;text-align:right;color:#00d4ff;">' + fmt(d.convertedAuto || 0) + '</td>';
                html += '</tr>';
            }
            html += '  </tbody></table>';
            html += '</div>';
            html += '<div style="color:#888;font-size:10.5px;margin-top:6px;">📱 Auto = detectados con app DESPUÉS de la etiqueta (sin que el agente confirme manualmente). ✅ Instaló = el agente tildó manualmente desde la sección de Recontactación.</div>';
        } else {
            html += '<div style="color:#aaa;font-size:11.5px;text-align:center;padding:14px;">Todavía no hay etiquetas Callbell registradas.</div>';
        }

        html += '  </div>';
        html += '</details>';
    }

    // === Evolución día por día ===
    const hist = (data._history || []).slice().sort((a, b) => (b.dayKey || '').localeCompare(a.dayKey || ''));
    if (hist.length >= 1) {
        html += '<details open style="background:rgba(0,212,255,0.04);border:1px solid rgba(0,212,255,0.20);border-radius:10px;padding:0;margin-bottom:14px;overflow:hidden;">';
        html += '  <summary style="cursor:pointer;padding:10px 14px;background:rgba(0,212,255,0.06);list-style:none;display:flex;justify-content:space-between;align-items:center;">';
        html += '    <span style="color:#00d4ff;font-weight:800;font-size:13px;letter-spacing:0.5px;">📈 EVOLUCIÓN DÍA POR DÍA · ' + hist.length + ' días</span>';
        html += '    <span style="color:#888;font-size:10.5px;">tocá para abrir/cerrar ▾</span>';
        html += '  </summary>';
        html += '  <div style="padding:12px 14px;">';
        html += '    <div style="color:#aaa;font-size:11px;margin-bottom:8px;">Snapshot diario automático (~03:00 ART) o cada vez que entrás a esta sección. Los Δ comparan con el día anterior.</div>';

        const fmt = n => Number(n || 0).toLocaleString('es-AR');
        const delta = (cur, prev) => {
            if (prev == null) return '';
            const d = (cur || 0) - (prev || 0);
            if (d === 0) return ' <span style="color:#666;">·</span>';
            const sign = d > 0 ? '+' : '';
            return ' <span style="color:' + (d > 0 ? '#66ff66' : '#ff8080') + ';font-size:9.5px;">' + sign + fmt(d) + '</span>';
        };

        html += '    <div style="overflow-x:auto;max-height:340px;overflow-y:auto;">';
        html += '<table style="width:100%;border-collapse:collapse;font-size:11.5px;min-width:680px;">';
        html += '  <thead><tr style="background:rgba(255,255,255,0.04);position:sticky;top:0;">';
        html += '    <th style="text-align:left;padding:7px 10px;color:#aaa;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">Día</th>';
        html += '    <th style="text-align:right;padding:7px 10px;color:#aaa;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">Total registrados</th>';
        html += '    <th style="text-align:right;padding:7px 10px;color:#7cffb3;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">📱 Con app</th>';
        html += '    <th style="text-align:right;padding:7px 10px;color:#25d366;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">🔔 Con notifs</th>';
        html += '    <th style="text-align:right;padding:7px 10px;color:#00d4ff;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">✅ Push directo</th>';
        html += '    <th style="text-align:right;padding:7px 10px;color:#ffaa44;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">App s/ notifs</th>';
        html += '    <th style="text-align:right;padding:7px 10px;color:#888;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">Sin app</th>';
        html += '    <th style="text-align:right;padding:7px 10px;color:#aaa;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">% app</th>';
        html += '  </tr></thead><tbody>';
        for (let i = 0; i < hist.length; i++) {
            const s = hist[i];
            const prev = hist[i + 1] || null;
            const total = s.totalUsers || 0;
            const pctApp = total > 0 ? ((s.withApp / total) * 100).toFixed(1) : '0';
            const isToday = i === 0;
            html += '<tr style="border-bottom:1px solid rgba(255,255,255,0.04);' + (isToday ? 'background:rgba(102,255,102,0.04);' : '') + '">';
            html += '  <td style="padding:5px 10px;color:#fff;font-weight:600;font-size:11px;">' + escapeHtml(s.dayKey || '') + (isToday ? ' <span style="color:#66ff66;font-size:9.5px;">● HOY</span>' : '') + '</td>';
            html += '  <td style="padding:5px 10px;text-align:right;color:#bbb;">' + fmt(s.totalUsers) + delta(s.totalUsers, prev && prev.totalUsers) + '</td>';
            html += '  <td style="padding:5px 10px;text-align:right;color:#7cffb3;font-weight:700;">' + fmt(s.withApp) + delta(s.withApp, prev && prev.withApp) + '</td>';
            html += '  <td style="padding:5px 10px;text-align:right;color:#25d366;">' + fmt(s.withNotifs) + delta(s.withNotifs, prev && prev.withNotifs) + '</td>';
            html += '  <td style="padding:5px 10px;text-align:right;color:#00d4ff;font-weight:700;">' + fmt(s.withBoth) + delta(s.withBoth, prev && prev.withBoth) + '</td>';
            html += '  <td style="padding:5px 10px;text-align:right;color:#ffaa44;">' + fmt(s.withAppNoNotifs) + delta(s.withAppNoNotifs, prev && prev.withAppNoNotifs) + '</td>';
            html += '  <td style="padding:5px 10px;text-align:right;color:#888;">' + fmt(s.sinApp) + delta(s.sinApp, prev && prev.sinApp) + '</td>';
            html += '  <td style="padding:5px 10px;text-align:right;color:#fff;font-weight:600;">' + pctApp + '%</td>';
            html += '</tr>';
        }
        html += '  </tbody></table>';
        html += '    </div>';
        html += '  </div>';
        html += '</details>';
    }

    // Plataformas
    const plats = data.platforms || [];
    if (plats.length > 0) {
        html += '<div style="background:rgba(0,0,0,0.30);border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:12px;margin-bottom:14px;">';
        html += '  <div style="color:#aaa;font-size:11px;text-transform:uppercase;letter-spacing:1px;margin-bottom:8px;">Plataformas (tokens standalone)</div>';
        html += '  <div style="display:flex;gap:10px;flex-wrap:wrap;">';
        for (const p of plats) {
            html += '<div style="background:rgba(255,255,255,0.04);padding:8px 14px;border-radius:8px;">';
            html += '<div style="color:#fff;font-weight:700;">' + escapeHtml(p.platform) + '</div>';
            html += '<div style="color:#7cffb3;font-size:18px;font-weight:900;">' + fmt(p.count) + '</div>';
            html += '</div>';
        }
        html += '  </div>';
        html += '</div>';
    }

    // Tabla por equipo
    const teams = data.byTeam || [];
    html += '<div style="background:rgba(0,0,0,0.30);border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:10px;">';
    html += '  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">';
    html += '    <span style="color:#aaa;font-size:11px;text-transform:uppercase;letter-spacing:1px;">Por equipo · ' + teams.length + ' equipos con users con app</span>';
    html += '  </div>';
    html += '  <div style="overflow-x:auto;max-height:60vh;overflow-y:auto;">';
    html += '<table style="width:100%;border-collapse:collapse;font-size:12px;min-width:680px;">';
    html += '<thead><tr style="background:rgba(255,255,255,0.04);position:sticky;top:0;">';
    html += '  <th style="text-align:left;padding:8px 10px;color:#ddd;border-bottom:1px solid rgba(255,255,255,0.10);">Equipo</th>';
    html += '  <th style="text-align:right;padding:8px 10px;color:#7cffb3;border-bottom:1px solid rgba(255,255,255,0.10);">Con app</th>';
    html += '  <th style="text-align:right;padding:8px 10px;color:#00d4ff;border-bottom:1px solid rgba(255,255,255,0.10);">Push directo</th>';
    html += '  <th style="text-align:right;padding:8px 10px;color:#ffaa44;border-bottom:1px solid rgba(255,255,255,0.10);">App sin notifs</th>';
    html += '  <th style="text-align:right;padding:8px 10px;color:#aaa;border-bottom:1px solid rgba(255,255,255,0.10);">Total registrados</th>';
    html += '  <th style="text-align:right;padding:8px 10px;color:#ddd;border-bottom:1px solid rgba(255,255,255,0.10);">% del equipo con app</th>';
    html += '</tr></thead><tbody>';
    for (const t of teams) {
        html += '<tr style="border-bottom:1px solid rgba(255,255,255,0.04);">';
        html += '  <td style="padding:7px 10px;color:#fff;font-weight:600;">' + escapeHtml(t.team) + '</td>';
        html += '  <td style="padding:7px 10px;text-align:right;color:#7cffb3;font-weight:700;">' + fmt(t.withApp) + '</td>';
        html += '  <td style="padding:7px 10px;text-align:right;color:#00d4ff;">' + fmt(t.withBoth) + '</td>';
        html += '  <td style="padding:7px 10px;text-align:right;color:#ffaa44;">' + fmt(t.withAppNoNotifs) + '</td>';
        html += '  <td style="padding:7px 10px;text-align:right;color:#bbb;">' + fmt(t.totalRegistered) + '</td>';
        html += '  <td style="padding:7px 10px;text-align:right;color:#fff;font-weight:600;">' + (t.pctOfTeam || 0) + '%</td>';
        html += '</tr>';
    }
    html += '</tbody></table>';
    html += '  </div>';
    html += '</div>';

    return html;
}

function _kpiCardLite(label, value, color, sub) {
    return '<div style="background:rgba(0,0,0,0.30);border:1px solid rgba(255,255,255,0.08);border-radius:10px;padding:12px 14px;">' +
        '<div style="color:#888;font-size:10px;text-transform:uppercase;letter-spacing:1px;margin-bottom:4px;">' + escapeHtml(label) + '</div>' +
        '<div style="color:' + color + ';font-size:24px;font-weight:900;line-height:1;">' + escapeHtml(value) + '</div>' +
        (sub ? '<div style="color:#aaa;font-size:10.5px;margin-top:4px;">' + escapeHtml(sub) + '</div>' : '') +
    '</div>';
}

function _recontactDescribeFilters() {
    const f = window._recontactFilters || {};
    const parts = [];
    if (f.bucket && f.bucket !== 'all') parts.push('bucket=' + f.bucket);
    if (f.tier && f.tier !== 'all') parts.push('tier=' + f.tier);
    if (f.appStatus && f.appStatus !== 'all') parts.push('app=' + f.appStatus);
    if (f.line && f.line !== 'all') parts.push('linea=' + f.line);
    return parts.length ? parts.join(' · ') : 'todos';
}

function _recontactSetLineFilter(val) {
    if (!window._recontactFilters) window._recontactFilters = {};
    window._recontactFilters.line = val || 'all';
    loadRecontactSection();
}

function _renderRecontactDashboard(summary, items) {
    const fmt = n => Number(n || 0).toLocaleString('es-AR');
    const t = summary.tiers || {};
    const b = summary.buckets || {};
    const f = window._recontactFilters || { tier: 'all', bucket: 'all', appStatus: 'all' };

    let html = '';

    // Banner sticky arriba de todo: "Guardar tildes". SIEMPRE visible mientras
    // estás en la sección, scroll-friendly. Cuando hay pending → rojo + count;
    // cuando todo guardado → verde apagado.
    html += '<div id="recontactSaveBanner" style="position:sticky;top:0;z-index:50;background:linear-gradient(135deg,#0f1729,#1a0033);border-bottom:2px solid rgba(155,48,255,0.40);padding:10px 14px;margin:-10px -14px 14px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;box-shadow:0 4px 14px rgba(0,0,0,0.35);">';
    html += '  <div style="color:#bbb;font-size:12px;line-height:1.4;">';
    html += '    <strong style="color:#fff;font-size:13px;">📞 Tildes Callbell</strong><br>';
    html += '    <span id="recontactSaveStatus" style="color:#888;">Tildá las casillas en cada fila. El sistema guarda automáticamente, pero tocá <strong style="color:#fff;">Guardar tildes</strong> si querés confirmar todos los cambios.</span>';
    html += '  </div>';
    html += '  <button type="button" id="recontactSaveAllBtn" onclick="recontactSaveAllTags()" style="padding:12px 22px;font-size:14px;font-weight:900;background:linear-gradient(135deg,#9b30ff,#5a1aaa);border:none;color:#fff;border-radius:9px;cursor:pointer;letter-spacing:0.5px;box-shadow:0 4px 14px rgba(155,48,255,0.35);min-width:200px;">💾 GUARDAR TILDES</button>';
    html += '</div>';

    // Banner del análisis activo (compartido entre todos los admins)
    if (_recontactState.savedAt) {
        const rel = _recontactRelTime(_recontactState.savedAt);
        const lbl = _recontactState.fileLabel ? ' · <strong style="color:#fff;">' + escapeHtml(_recontactState.fileLabel) + '</strong>' : '';
        const by = _recontactState.savedByUsername ? ' · subido por <strong style="color:#fff;">' + escapeHtml(_recontactState.savedByUsername) + '</strong>' : '';
        html += '<div style="background:rgba(102,255,102,0.06);border:1px solid rgba(102,255,102,0.30);border-radius:8px;padding:8px 12px;margin-bottom:12px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;">';
        html += '  <span style="color:#bbb;font-size:11.5px;">📂 Análisis activo (compartido) · <span style="color:#66ff66;">' + rel + '</span>' + lbl + by + ' · expira en 7 días</span>';
        html += '  <button type="button" onclick="recontactReset()" style="padding:5px 10px;font-size:11px;background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.20);color:#fff;border-radius:6px;cursor:pointer;">🗑 Descartar y subir otra</button>';
        html += '</div>';
    }

    // Historial de análisis pasados (si hay >=2 entradas)
    const history = _recontactLoadHistory();
    if (history.length >= 1) {
        html += _renderRecontactHistoryCard(history);
    }

    // Header con botones de acción
    html += '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:14px;">';
    html += '  <div style="color:#00d4ff;font-weight:800;font-size:15px;">📊 Análisis de ' + fmt(summary.totalAnalyzed) + ' usuarios</div>';
    html += '  <div style="display:flex;gap:8px;flex-wrap:wrap;">';
    html += '    <button type="button" onclick="recontactDownloadXlsx()" style="padding:9px 16px;font-size:12.5px;font-weight:700;background:linear-gradient(135deg,#1a73e8,#0d47a1);border:none;color:#fff;border-radius:7px;cursor:pointer;" title="XLSX con varias hojas: una por bucket, una por estado de app, resumen, y todos por prioridad">📊 XLSX por hojas</button>';
    html += '    <button type="button" onclick="recontactDownloadCsv()" style="padding:9px 16px;font-size:12.5px;font-weight:700;background:linear-gradient(135deg,#25d366,#128c4f);border:none;color:#fff;border-radius:7px;cursor:pointer;">📥 CSV simple</button>';
    html += '    <button type="button" onclick="recontactReset()" style="padding:9px 14px;font-size:12.5px;font-weight:700;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.20);color:#fff;border-radius:7px;cursor:pointer;">🔄 Subir otra lista</button>';
    html += '  </div>';
    html += '</div>';

    // KPIs grandes
    html += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-bottom:12px;">';
    html += _kpiCard('Encontrados en base', fmt(summary.foundInDb), '#25d366', `de ${fmt(summary.totalAnalyzed)}`);
    html += _kpiCard('No encontrados', fmt(summary.notFound), '#ff8080', 'usernames inválidos');
    html += _kpiCard('Con app+notifs', fmt(summary.withNotifs), '#00d4ff', 'push directo');
    html += _kpiCard('Sin app o sin notifs', fmt(summary.totalAnalyzed - summary.withNotifs), '#ffaa44', 'recontactar por WhatsApp');
    html += _kpiCard('Bono total sugerido', '$' + fmt(summary.totalRecoverableValue || 0), '#ffd700', 'inversión recuperación');
    html += '</div>';

    // KPIs del archivo — sólo si trajo Type/Amount/User.
    const hasFileTx = (summary.fileTotalDeposits || 0) + (summary.fileTotalWithdraws || 0) + (summary.fileTotalBonuses || 0) > 0;
    if (hasFileTx) {
        const net = (summary.fileTotalDeposits || 0) - (summary.fileTotalWithdraws || 0);
        html += '<div style="background:rgba(0,212,255,0.04);border:1px solid rgba(0,212,255,0.18);border-radius:10px;padding:10px 12px;margin-bottom:12px;">';
        html += '  <div style="color:#00d4ff;font-size:11px;text-transform:uppercase;letter-spacing:1px;margin-bottom:8px;">📄 Datos del archivo subido</div>';
        html += '  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;">';
        html += _kpiCard('Total cargas',   '$' + fmt(summary.fileTotalDeposits),  '#25d366', fmt(summary.fileCountDeposits) + ' movimientos');
        html += _kpiCard('Total retiros',  '$' + fmt(summary.fileTotalWithdraws), '#ff5050', fmt(summary.fileCountWithdraws) + ' movimientos');
        html += _kpiCard('Total bonos',    '$' + fmt(summary.fileTotalBonuses),   '#ffd700', fmt(summary.fileCountBonuses) + ' bonificaciones');
        html += _kpiCard('Neto (cargas - retiros)', (net < 0 ? '-$' : '$') + fmt(Math.abs(net)), net >= 0 ? '#25d366' : '#ff5050', net >= 0 ? 'saldo positivo' : 'retiraron más de lo que cargaron');
        html += '  </div>';
        html += '</div>';
    }

    // Buckets de actividad — clickables como filtro
    html += '<div style="background:rgba(0,0,0,0.20);border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:12px;margin-bottom:12px;">';
    html += '  <div style="color:#aaa;font-size:11px;text-transform:uppercase;letter-spacing:1px;margin-bottom:8px;">Por actividad (días sin cargar) — tocá para filtrar</div>';
    html += '  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;">';
    const bucketDef = [
        { k: 'calientes', label: '🔥 Calientes',  sub: '0-10 días',   color: '#ff5050' },
        { k: 'enRiesgo',  label: '⚠ En riesgo',   sub: '10-20 días',  color: '#ffaa44' },
        { k: 'perdidos',  label: '💔 Perdidos',   sub: '20-30 días',  color: '#9b30ff' },
        { k: 'inactivos', label: '☠ Inactivos',   sub: '+30 días',    color: '#888' }
    ];
    for (const bk of bucketDef) {
        const isActive = f.bucket === bk.k;
        html += '<div onclick="_recontactFilterSet(\'bucket\',\'' + (isActive ? 'all' : bk.k) + '\')" style="cursor:pointer;background:rgba(' + _hexToRgb(bk.color) + ',0.10);border:' + (isActive ? '2px' : '1px') + ' solid ' + bk.color + ';border-radius:8px;padding:9px;">';
        html += '  <div style="color:' + bk.color + ';font-weight:800;font-size:12px;">' + bk.label + '</div>';
        html += '  <div style="color:#fff;font-size:22px;font-weight:900;margin-top:2px;">' + fmt(b[bk.k] || 0) + '</div>';
        html += '  <div style="color:#888;font-size:10px;">' + bk.sub + '</div>';
        html += '</div>';
    }
    html += '  </div>';
    html += '</div>';

    // Tiers — clickables como filtro
    html += '<div style="background:rgba(0,0,0,0.20);border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:12px;margin-bottom:12px;">';
    html += '  <div style="color:#aaa;font-size:11px;text-transform:uppercase;letter-spacing:1px;margin-bottom:8px;">Por tier — tocá para filtrar</div>';
    html += '  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;">';
    const tierDef = [
        { k: 'VIP',       label: '🏆 VIP',     color: '#ffd700' },
        { k: 'ORO',       label: '🥇 ORO',     color: '#f7931e' },
        { k: 'PLATA',     label: '🥈 PLATA',   color: '#c0c0c0' },
        { k: 'BRONCE',    label: '🥉 BRONCE',  color: '#cd7f32' },
        { k: 'NUEVO',     label: '🆕 NUEVO',   color: '#1a73e8' },
        { k: 'SIN_DATOS', label: '⚪ Sin datos', color: '#666' }
    ];
    for (const td of tierDef) {
        const isActive = f.tier === td.k;
        html += '<div onclick="_recontactFilterSet(\'tier\',\'' + (isActive ? 'all' : td.k) + '\')" style="cursor:pointer;background:rgba(' + _hexToRgb(td.color) + ',0.10);border:' + (isActive ? '2px' : '1px') + ' solid ' + td.color + ';border-radius:8px;padding:8px;">';
        html += '  <div style="color:' + td.color + ';font-weight:800;font-size:11.5px;">' + td.label + '</div>';
        html += '  <div style="color:#fff;font-size:18px;font-weight:900;margin-top:2px;">' + fmt(t[td.k] || 0) + '</div>';
        html += '</div>';
    }
    html += '  </div>';
    html += '</div>';

    // Filtros adicionales
    html += '<div style="background:rgba(0,0,0,0.20);border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:10px 12px;margin-bottom:12px;display:flex;gap:10px;flex-wrap:wrap;align-items:center;">';
    html += '  <span style="color:#aaa;font-size:11px;text-transform:uppercase;letter-spacing:1px;">App / Notifs:</span>';
    const appOpts = [
        { k: 'all', label: 'Todos' },
        { k: 'with-notifs', label: '📱 Con app+notifs (push)' },
        { k: 'without-app', label: '💬 Sin app (WhatsApp)' },
        { k: 'app-no-notifs', label: '🔕 Con app pero sin notifs' }
    ];
    for (const o of appOpts) {
        const active = f.appStatus === o.k;
        html += '<button type="button" onclick="_recontactFilterSet(\'appStatus\',\'' + o.k + '\')" style="padding:5px 10px;font-size:11px;font-weight:600;background:' + (active ? 'rgba(0,212,255,0.20)' : 'rgba(255,255,255,0.04)') + ';border:1px solid ' + (active ? '#00d4ff' : 'rgba(255,255,255,0.15)') + ';color:' + (active ? '#00d4ff' : '#bbb') + ';border-radius:6px;cursor:pointer;">' + o.label + '</button>';
    }
    html += '</div>';

    // === Resumen Callbell — etiquetas tildadas en este análisis ===
    let cbEtiq = 0, cbWa = 0, cbInst = 0, cbNoCont = 0, cbAppDespues = 0;
    for (const it of items) {
        if (it.cbEtiqueta) cbEtiq++;
        if (it.cbWa) cbWa++;
        if (it.cbResp === 'instalo') cbInst++;
        if (it.cbResp === 'no_contesto') cbNoCont++;
        if (it.cbConvertedAt && !it.cbHadAppAtFirstTag) cbAppDespues++;
    }
    if (cbEtiq + cbWa + cbInst + cbNoCont + cbAppDespues > 0) {
        const fmtN = n => Number(n || 0).toLocaleString('es-AR');
        html += '<div style="background:linear-gradient(135deg,rgba(155,48,255,0.06),rgba(124,255,179,0.04));border:1px solid rgba(155,48,255,0.30);border-radius:10px;padding:10px 12px;margin-bottom:12px;">';
        html += '  <div style="color:#9b30ff;font-size:11px;text-transform:uppercase;letter-spacing:1px;margin-bottom:6px;font-weight:700;">📞 Tracking Callbell — sobre los items del archivo</div>';
        html += '  <div style="display:flex;gap:14px;flex-wrap:wrap;font-size:12px;color:#bbb;">';
        html += '    <span>🏷 Etiquetados: <strong style="color:#9b30ff;">' + fmtN(cbEtiq) + '</strong></span>';
        html += '    <span>📤 WhatsApp enviado: <strong style="color:#25d366;">' + fmtN(cbWa) + '</strong></span>';
        html += '    <span>✅ Instaló (manual): <strong style="color:#7cffb3;">' + fmtN(cbInst) + '</strong></span>';
        html += '    <span>✕ No contestó: <strong style="color:#ff8080;">' + fmtN(cbNoCont) + '</strong></span>';
        if (cbAppDespues > 0) html += '    <span>📱 Detectados con app después de etiquetar: <strong style="color:#00d4ff;">' + fmtN(cbAppDespues) + '</strong></span>';
        html += '  </div>';
        html += '</div>';
    }

    // === Filtro por línea + descargas filtradas ===
    const lineOpts = _recontactBuildLineOptions(items);
    const filteredCount = _filterRecontactItems(items, f).length;
    html += '<div style="background:linear-gradient(135deg,rgba(37,211,102,0.06),rgba(0,212,255,0.04));border:1px solid rgba(37,211,102,0.30);border-radius:10px;padding:10px 12px;margin-bottom:12px;">';
    html += '  <div style="display:flex;flex-wrap:wrap;align-items:center;gap:10px;">';
    html += '    <span style="color:#25d366;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:1px;">📞 Filtrar por línea + descargar:</span>';
    html += '    <select id="recontactLineSelect" onchange="_recontactSetLineFilter(this.value)" style="padding:6px 8px;font-size:12px;background:rgba(0,0,0,0.45);border:1px solid rgba(255,255,255,0.18);color:#fff;border-radius:6px;min-width:200px;">';
    html += '      <option value="all"' + (f.line === 'all' ? ' selected' : '') + '>TODAS las líneas (' + items.length + ')</option>';
    for (const o of lineOpts) {
        html += '      <option value="' + escapeHtml(o.key) + '"' + (f.line === o.key ? ' selected' : '') + '>' + escapeHtml(o.label) + '</option>';
    }
    html += '    </select>';
    html += '    <span style="color:#bbb;font-size:11.5px;"><strong style="color:#fff;">' + filteredCount + '</strong> con filtros actuales</span>';
    html += '    <button type="button" onclick="recontactDownloadSimple()" style="padding:7px 12px;font-size:11.5px;font-weight:700;background:linear-gradient(135deg,#25d366,#128c4f);border:none;color:#fff;border-radius:6px;cursor:pointer;" title="CSV con name + phone + linea + equipo (listo para WhatsApp)">📞 Contacto + phone</button>';
    html += '    <button type="button" onclick="recontactDownloadDetailed()" style="padding:7px 12px;font-size:11.5px;font-weight:700;background:linear-gradient(135deg,#1a73e8,#0d47a1);border:none;color:#fff;border-radius:6px;cursor:pointer;" title="CSV con name, phone, linea, equipo, mensaje sugerido, rango (días), carga, descarga, diferencia, bono sugerido y app/notifs">📋 Lista detallada</button>';
    html += '    <button type="button" onclick="recontactDownloadXlsxByTeam()" style="padding:7px 12px;font-size:11.5px;font-weight:700;background:linear-gradient(135deg,#9b30ff,#5a1aaa);border:none;color:#fff;border-radius:6px;cursor:pointer;" title="XLSX con una hoja por equipo + resumen al inicio. Respeta los filtros actuales.">📊 XLSX por equipos</button>';
    html += '  </div>';
    html += '  <div style="color:#888;font-size:10.5px;margin-top:6px;line-height:1.5;">Las descargas respetan TODOS los filtros activos (panorama, tier, app/notifs, línea). El campo <strong>phone</strong> usa el del cliente si está registrado, si no usa el de la línea asignada. Si no hay ni teléfono ni línea, queda vacío pero <strong>la fila igual se exporta</strong> (con el username).</div>';
    html += '</div>';

    // ====== PANORAMA: matriz bucket × estado de app ======
    // Te dice cuántos hay en cada combinación + cuánto monto del archivo, y
    // cada celda es clickable para filtrar la tabla de abajo.
    html += _renderRecontactPanorama(items, f);

    // Tabla con items filtrados
    const filtered = _filterRecontactItems(items, f);
    html += '<div style="background:rgba(0,0,0,0.30);border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:10px;">';
    html += '  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex-wrap:wrap;gap:8px;">';
    html += '    <span style="color:#aaa;font-size:11px;text-transform:uppercase;letter-spacing:1px;">Mostrando ' + filtered.length + ' de ' + items.length + ' (top por prioridad)</span>';
    html += '  </div>';
    html += '  <div style="overflow-x:auto;max-height:60vh;overflow-y:auto;">';
    const minWidth = hasFileTx ? 1480 : 1220;
    html += '<table style="width:100%;border-collapse:collapse;font-size:11.5px;min-width:' + minWidth + 'px;">';
    html += '  <thead><tr style="background:rgba(255,255,255,0.04);position:sticky;top:0;">';
    html += '    <th style="text-align:left;padding:7px 10px;color:#ddd;border-bottom:1px solid rgba(255,255,255,0.10);">#</th>';
    html += '    <th style="text-align:left;padding:7px 10px;color:#ddd;border-bottom:1px solid rgba(255,255,255,0.10);">Usuario</th>';
    html += '    <th style="text-align:left;padding:7px 10px;color:#ddd;border-bottom:1px solid rgba(255,255,255,0.10);">Tier</th>';
    html += '    <th style="text-align:right;padding:7px 10px;color:#ddd;border-bottom:1px solid rgba(255,255,255,0.10);">Días</th>';
    html += '    <th style="text-align:right;padding:7px 10px;color:#ddd;border-bottom:1px solid rgba(255,255,255,0.10);">$ 30d</th>';
    if (hasFileTx) {
        html += '    <th style="text-align:right;padding:7px 10px;color:#25d366;border-bottom:1px solid rgba(255,255,255,0.10);" title="$ total y cantidad de cargas en el archivo">$ Cargas (arch) · #</th>';
        html += '    <th style="text-align:right;padding:7px 10px;color:#ff5050;border-bottom:1px solid rgba(255,255,255,0.10);" title="$ total y cantidad de retiros en el archivo">$ Retiros (arch) · #</th>';
        html += '    <th style="text-align:right;padding:7px 10px;color:#ffd700;border-bottom:1px solid rgba(255,255,255,0.10);" title="$ total y cantidad de bonos en el archivo">$ Bonos (arch) · #</th>';
    }
    html += '    <th style="text-align:left;padding:7px 10px;color:#ddd;border-bottom:1px solid rgba(255,255,255,0.10);">App</th>';
    html += '    <th style="text-align:left;padding:7px 10px;color:#ddd;border-bottom:1px solid rgba(255,255,255,0.10);" title="Equipo asignado y número de línea WhatsApp">Equipo · Línea</th>';
    html += '    <th style="text-align:left;padding:7px 10px;color:#ddd;border-bottom:1px solid rgba(255,255,255,0.10);">Tel cliente</th>';
    html += '    <th style="text-align:center;padding:7px 6px;color:#9b30ff;border-bottom:1px solid rgba(255,255,255,0.10);" title="Etiquetado en Callbell para recontactar">🏷 Etiq</th>';
    html += '    <th style="text-align:center;padding:7px 6px;color:#25d366;border-bottom:1px solid rgba(255,255,255,0.10);" title="WhatsApp ya enviado">📤 WA</th>';
    html += '    <th style="text-align:center;padding:7px 6px;color:#7cffb3;border-bottom:1px solid rgba(255,255,255,0.10);" title="Confirmar manualmente que el cliente instaló la app">✅ Inst</th>';
    html += '    <th style="text-align:center;padding:7px 6px;color:#ff8080;border-bottom:1px solid rgba(255,255,255,0.10);" title="Confirmar que el cliente no contestó">✕ NoCont</th>';
    html += '    <th style="text-align:left;padding:7px 10px;color:#ddd;border-bottom:1px solid rgba(255,255,255,0.10);">Estrategia</th>';
    html += '    <th style="text-align:right;padding:7px 10px;color:#ddd;border-bottom:1px solid rgba(255,255,255,0.10);">Bono</th>';
    html += '    <th style="text-align:left;padding:7px 10px;color:#ddd;border-bottom:1px solid rgba(255,255,255,0.10);">Mensaje sugerido</th>';
    html += '  </tr></thead><tbody>';
    const tierColor = { VIP: '#ffd700', ORO: '#f7931e', PLATA: '#c0c0c0', BRONCE: '#cd7f32', NUEVO: '#1a73e8', SIN_DATOS: '#666' };
    const bucketColor = { calientes: '#ff5050', enRiesgo: '#ffaa44', perdidos: '#9b30ff', inactivos: '#888' };
    const max = 500; // cap visual
    const sliced = filtered.slice(0, max);
    for (let i = 0; i < sliced.length; i++) {
        const it = sliced[i];
        html += '<tr style="border-bottom:1px solid rgba(255,255,255,0.04);">';
        html += '  <td style="padding:5px 10px;color:#888;">' + (i + 1) + '</td>';
        html += '  <td style="padding:5px 10px;color:#fff;font-weight:600;">' + escapeHtml(it.username || '') + '</td>';
        html += '  <td style="padding:5px 10px;color:' + (tierColor[it.tier] || '#aaa') + ';font-weight:700;">' + escapeHtml(it.tier || '—') + '</td>';
        html += '  <td style="padding:5px 10px;text-align:right;color:' + (bucketColor[it.bucket] || '#aaa') + ';font-family:monospace;">' + (it.daysSinceLastDeposit == null ? '—' : it.daysSinceLastDeposit) + '</td>';
        html += '  <td style="padding:5px 10px;text-align:right;color:#fff;">' + (it.deposits30d ? '$' + fmt(it.deposits30d) : '—') + '</td>';
        if (hasFileTx) {
            const cd = it.fileCountDeposits || 0;
            const cw = it.fileCountWithdraws || 0;
            const cb = it.fileCountBonuses || 0;
            html += '  <td style="padding:5px 10px;text-align:right;color:#25d366;font-family:monospace;">' + (it.fileDeposits ? '$' + fmt(it.fileDeposits) + ' <span style="color:#888;">· ' + cd + '</span>' : '—') + '</td>';
            html += '  <td style="padding:5px 10px;text-align:right;color:#ff5050;font-family:monospace;">' + (it.fileWithdraws ? '$' + fmt(it.fileWithdraws) + ' <span style="color:#888;">· ' + cw + '</span>' : '—') + '</td>';
            html += '  <td style="padding:5px 10px;text-align:right;color:#ffd700;font-family:monospace;">' + (it.fileBonuses ? '$' + fmt(it.fileBonuses) + ' <span style="color:#888;">· ' + cb + '</span>' : '—') + '</td>';
        }
        html += '  <td style="padding:5px 10px;">' + (it.hasApp ? (it.hasNotifs ? '<span style="color:#25d366;">📱✓</span>' : '<span style="color:#ffaa44;">📱🔕</span>') : '<span style="color:#888;">—</span>') + '</td>';
        // Equipo + línea en una sola celda — sale de User O del UserLineLookup pre-cargado.
        const teamLineParts = [];
        if (it.team) teamLineParts.push('<span style="color:#fff;font-weight:600;">' + escapeHtml(it.team) + '</span>');
        if (it.linePhone) teamLineParts.push('<span style="color:#bbb;font-family:monospace;font-size:10.5px;">' + escapeHtml(it.linePhone) + '</span>');
        html += '  <td style="padding:5px 10px;font-size:10.5px;">' + (teamLineParts.length ? teamLineParts.join('<br>') : '<span style="color:#666;">sin línea</span>') + '</td>';
        html += '  <td style="padding:5px 10px;color:#bbb;font-family:monospace;font-size:10.5px;">' + escapeHtml(it.phone || '—') + '</td>';
        // 4 checkboxes Callbell — etiqueta, wa, instalo, no_contesto.
        // Usamos data-* + delegación para evitar bugs de escape en HTML inline.
        const userAttr = String(it.username || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
        const cbBox = (action, isOn, color) => {
            const onCheck = !!isOn;
            return '<td style="padding:4px 6px;text-align:center;">'
                + '<input type="checkbox" class="cb-callbell-toggle"'
                + ' data-user="' + userAttr + '" data-action="' + action + '"'
                + (onCheck ? ' checked' : '')
                + ' style="cursor:pointer;width:16px;height:16px;accent-color:' + color + ';">'
                + '</td>';
        };
        html += cbBox('etiqueta', it.cbEtiqueta, '#9b30ff');
        html += cbBox('wa', it.cbWa, '#25d366');
        html += cbBox('instalo', it.cbResp === 'instalo', '#7cffb3');
        html += cbBox('no_contesto', it.cbResp === 'no_contesto', '#ff8080');
        html += '  <td style="padding:5px 10px;color:#ffd700;font-weight:600;font-size:11px;">' + escapeHtml(it.strategy || '—') + '</td>';
        html += '  <td style="padding:5px 10px;text-align:right;color:#25d366;font-weight:700;">$' + fmt(it.suggestedBonus || 0) + '</td>';
        html += '  <td style="padding:5px 10px;color:#ddd;font-size:11px;max-width:340px;">' + escapeHtml(it.suggestedMessage || '') + '</td>';
        html += '</tr>';
    }
    if (filtered.length > max) {
        const colspan = hasFileTx ? 18 : 15;
        html += '<tr><td colspan="' + colspan + '" style="padding:10px;text-align:center;color:#666;font-style:italic;">... ' + (filtered.length - max) + ' más en el CSV completo</td></tr>';
    }
    html += '  </tbody></table>';
    html += '</div></div>';

    return html;
}

function _kpiCard(label, value, color, sub) {
    return '<div style="background:rgba(0,0,0,0.30);border:1px solid rgba(255,255,255,0.08);border-radius:10px;padding:10px 12px;">' +
        '<div style="color:#888;font-size:10px;text-transform:uppercase;letter-spacing:1px;margin-bottom:3px;">' + escapeHtml(label) + '</div>' +
        '<div style="color:' + color + ';font-size:20px;font-weight:900;line-height:1;">' + escapeHtml(value) + '</div>' +
        (sub ? '<div style="color:#aaa;font-size:10px;margin-top:3px;">' + escapeHtml(sub) + '</div>' : '') +
    '</div>';
}

// Tarjeta "Post recontactación": lista las mejoras post-recontactación.
//   - Conversiones: users que marcaste con ✅ etiqueta y que después instalaron la app.
//   - Mejora archivo-a-archivo: cuando subís otro XLSX con fecha distinta, compara
//     contra el análisis anterior y lista los users que mejoraron entre ambos
//     (instalaron app, subieron de bucket de actividad).
//   - Evolución histórica: usa RecontactHistory para mostrar timeline de análisis
//     con métricas reales (con app, %, bucket counts) y deltas archivo-a-archivo.
function _renderRecontactConversionsCard(conversions, history, baseStats) {
    const improvementHtml = _renderRecontactImprovementSection();
    const historyHtml = _renderRecontactFileEvolution(history || [], baseStats);
    if (!conversions || conversions.length === 0) {
        return '<div style="background:rgba(0,212,255,0.05);border:1px solid rgba(0,212,255,0.20);border-radius:10px;padding:14px;margin-top:18px;">' +
            '<div style="color:#00d4ff;font-weight:800;font-size:14px;margin-bottom:6px;">📊 Post recontactación</div>' +
            '<div style="color:#888;font-size:12px;">Todavía no hay conversiones registradas (etiquetados que instalaron app). Cuando alguien que marques con ✅ etiqueta instale la app, aparece acá con la fecha.</div>' +
            historyHtml +
            improvementHtml +
        '</div>';
    }

    const fmtDate = (d) => {
        if (!d) return '-';
        try {
            return new Date(d).toLocaleDateString('es-AR', { day: '2-digit', month: '2-digit', year: '2-digit' });
        } catch (_) { return '-'; }
    };
    const daysCol = (n) => {
        if (n == null) return '<span style="color:#888;">-</span>';
        if (n === 0) return '<span style="color:#25d366;font-weight:800;">mismo día</span>';
        const c = n <= 3 ? '#25d366' : (n <= 7 ? '#ffaa44' : '#aaa');
        return '<span style="color:' + c + ';font-weight:700;">' + n + 'd</span>';
    };

    let html = '<div style="background:rgba(0,212,255,0.05);border:1px solid rgba(0,212,255,0.20);border-radius:10px;padding:14px;margin-top:18px;">';
    html += '  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;flex-wrap:wrap;gap:6px;">';
    html += '    <div style="color:#00d4ff;font-weight:800;font-size:14px;">📊 Post recontactación</div>';
    html += '    <div style="color:#888;font-size:11px;">' + conversions.length + ' usuarios reactivados desde la última recontactación</div>';
    html += '  </div>';
    html += '  <div style="overflow-x:auto;">';
    html += '    <table style="width:100%;font-size:12px;border-collapse:collapse;">';
    html += '      <thead>';
    html += '        <tr style="background:rgba(0,212,255,0.10);color:#00d4ff;text-align:left;">';
    html += '          <th style="padding:7px 10px;">Usuario</th>';
    html += '          <th style="padding:7px 10px;">Etiquetado</th>';
    html += '          <th style="padding:7px 10px;">Instaló app</th>';
    html += '          <th style="padding:7px 10px;text-align:center;">Días</th>';
    html += '          <th style="padding:7px 10px;">Equipo</th>';
    html += '          <th style="padding:7px 10px;">Cómo</th>';
    html += '          <th style="padding:7px 10px;text-align:center;color:#ff8080;" title="Borrar de la lista">🗑</th>';
    html += '        </tr>';
    html += '      </thead>';
    html += '      <tbody>';
    for (const c of conversions) {
        const como = c.convertedBy === 'manual' ? '✅ manual' : '🤖 auto';
        const safeUser = escapeHtml(c.username || '');
        html += '<tr style="border-bottom:1px solid rgba(255,255,255,0.06);">';
        html += '  <td style="padding:6px 10px;color:#fff;font-weight:600;">' + safeUser + '</td>';
        html += '  <td style="padding:6px 10px;color:#bbb;">' + fmtDate(c.etiquetadoAt) + '</td>';
        html += '  <td style="padding:6px 10px;color:#25d366;font-weight:700;">' + fmtDate(c.installedAt) + '</td>';
        html += '  <td style="padding:6px 10px;text-align:center;">' + daysCol(c.daysToInstall) + '</td>';
        html += '  <td style="padding:6px 10px;color:#aaa;">' + escapeHtml(c.team || '-') + '</td>';
        html += '  <td style="padding:6px 10px;color:#888;font-size:10.5px;">' + como + '</td>';
        html += '  <td style="padding:6px 10px;text-align:center;">';
        html += '    <button type="button" onclick="_recontactDeleteConversion(\'' + safeUser + '\')" title="Sacar a este usuario de la lista (no borra su etiqueta, solo lo saca de Post recontactación)" style="background:rgba(255,128,128,0.10);border:1px solid rgba(255,128,128,0.40);color:#ff8080;padding:3px 8px;border-radius:5px;cursor:pointer;font-size:11px;">🗑</button>';
        html += '  </td>';
        html += '</tr>';
    }
    html += '      </tbody>';
    html += '    </table>';
    html += '  </div>';
    html += historyHtml;
    html += _renderRecontactImprovementSection();
    html += '</div>';
    return html;
}

// Evolución archivo-por-archivo: usa RecontactHistory (server) para mostrar los
// últimos análisis con métricas reales y deltas. Si el archivo cambia entre
// análisis, muestra warning de que la comparación NO es de los mismos users.
function _renderRecontactFileEvolution(history, baseStats) {
    if (!Array.isArray(history) || history.length === 0) {
        return '<div style="color:#888;font-size:11px;margin-top:14px;padding:10px 12px;background:rgba(0,0,0,0.20);border-radius:6px;">📜 No hay análisis históricos todavía. Subí XLSXs en Recontactación para que aparezcan acá.</div>';
    }
    const fmt = n => Number(n || 0).toLocaleString('es-AR');
    const fmtDate = (d) => {
        try { return new Date(d).toLocaleString('es-AR', { day:'2-digit', month:'2-digit', year:'2-digit', hour:'2-digit', minute:'2-digit' }); }
        catch (_) { return '-'; }
    };
    const pct = (a, b) => (b > 0 ? ((a / b) * 100).toFixed(1) + '%' : '—');
    // Color del delta según signo (positivo = verde, negativo = rojo, cero = gris).
    const delta = (cur, prev, prefix) => {
        if (prev == null || prev === undefined) return '<span style="color:#666;">—</span>';
        const d = (cur || 0) - (prev || 0);
        if (d === 0) return '<span style="color:#666;">0</span>';
        const color = d > 0 ? '#66ff66' : '#ff8080';
        return '<span style="color:' + color + ';font-weight:700;">' + (d > 0 ? '+' : '') + fmt(d) + '</span>';
    };
    // History viene desc por fecha (más nuevo primero). Para deltas, comparamos
    // cada uno con el SIGUIENTE en la lista (más viejo).
    let html = '';
    html += '<div style="margin-top:14px;background:rgba(0,212,255,0.04);border:1px solid rgba(0,212,255,0.25);border-radius:10px;padding:12px;">';
    html += '  <div style="display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap;gap:6px;margin-bottom:10px;">';
    html += '    <div style="color:#00d4ff;font-weight:800;font-size:13px;text-transform:uppercase;letter-spacing:1px;">📊 Evolución archivo-por-archivo</div>';
    html += '    <div style="color:#888;font-size:11px;">' + history.length + ' análisis · más reciente arriba · Δ = vs análisis anterior</div>';
    html += '  </div>';
    html += '  <div style="color:#bbb;font-size:11.5px;margin-bottom:8px;background:rgba(255,170,68,0.06);border-left:3px solid #ffaa44;padding:6px 10px;border-radius:4px;">⚠ Los Δ son válidos como progreso real <strong>solo si el archivo es el MISMO</strong> entre análisis. Si el nombre del archivo cambia, los users son distintos y el delta es referencial.</div>';
    // Banner comparativo con la base TOTAL: aclara por qué los nros del archivo difieren de Equipamiento/Usuarios con app.
    if (baseStats) {
        const baseTotalUsers = baseStats.totalUsers || 0;
        const baseWithApp = baseStats.withApp || 0;
        const baseWithNotifs = baseStats.withNotifs || 0;
        const newest = history[0] || {};
        const fileWithApp = newest.withApp || 0;
        const coveragePct = baseWithApp > 0 ? ((fileWithApp / baseWithApp) * 100).toFixed(1) : '0';
        html += '  <div style="background:rgba(0,212,255,0.06);border-left:3px solid #00d4ff;padding:8px 12px;border-radius:4px;margin-bottom:10px;color:#fff;font-size:12px;">';
        html += '    <div style="color:#00d4ff;font-weight:700;margin-bottom:3px;">📊 Comparación con TU BASE TOTAL</div>';
        html += '    <div style="color:#bbb;line-height:1.5;">';
        html += '      Tu base actual: <strong>' + fmt(baseTotalUsers) + ' users registrados</strong> · <strong style="color:#25d366;">' + fmt(baseWithApp) + ' con app</strong> · <strong style="color:#ffd700;">' + fmt(baseWithNotifs) + ' con notifs</strong>.<br>';
        html += '      Tu último análisis cubre <strong style="color:#00d4ff;">' + fmt(fileWithApp) + ' users con app</strong> (= <strong>' + coveragePct + '% de tu base con app</strong>). Los ' + fmt(Math.max(0, baseWithApp - fileWithApp)) + ' restantes NO están en el XLSX.';
        html += '    </div>';
        html += '  </div>';
    }
    html += '  <div style="overflow-x:auto;">';
    html += '  <table style="width:100%;border-collapse:collapse;font-size:11.5px;">';
    html += '    <thead><tr style="background:rgba(0,212,255,0.10);color:#00d4ff;text-align:left;">';
    html += '      <th style="padding:7px 8px;">Fecha</th>';
    html += '      <th style="padding:7px 8px;">Archivo</th>';
    html += '      <th style="padding:7px 8px;text-align:right;" title="Total usernames en el archivo">📋 Usernames archivo</th>';
    html += '      <th style="padding:7px 8px;text-align:right;" title="Cuántos de esos usernames son users registrados en la plataforma">✓ Registrados</th>';
    html += '      <th style="padding:7px 8px;text-align:right;" title="De los registrados del archivo, cuántos tienen la PWA instalada">📱 Con app (archivo)</th>';
    html += '      <th style="padding:7px 8px;text-align:right;" title="% con app sobre los registrados del archivo">% app (archivo)</th>';
    html += '      <th style="padding:7px 8px;text-align:right;" title="Cobertura: % de tu base con app que está en este archivo">📊 Cobertura</th>';
    html += '      <th style="padding:7px 8px;text-align:right;" title="Suma de depósitos del archivo">💰 Cargas</th>';
    html += '      <th style="padding:7px 8px;text-align:right;" title="Bono total sugerido">🎁 Bono sug.</th>';
    html += '      <th style="padding:7px 8px;text-align:center;color:#ff8080;" title="Borrar entrada">🗑</th>';
    html += '    </tr></thead><tbody>';
    const baseWithApp = (baseStats && baseStats.withApp) || 0;
    for (let i = 0; i < history.length; i++) {
        const h = history[i] || {};
        const prev = history[i + 1] || null;
        const fileChanged = prev && h.fileLabel && prev.fileLabel && h.fileLabel !== prev.fileLabel;
        const fileChangedNote = fileChanged ? ' <span style="color:#ffaa44;" title="Archivo distinto al anterior — Δ no es comparación válida de usuarios">⚠</span>' : '';
        const total = h.totalAnalyzed || 0;
        const foundInDb = h.foundInDb || 0;
        const withApp = h.withApp || 0;
        const prevTotal = prev && prev.totalAnalyzed || 0;
        const prevFound = prev && prev.foundInDb || 0;
        const prevWithApp = prev && prev.withApp || 0;
        // % app del archivo: % sobre los REGISTRADOS (foundInDb), no sobre el total del XLSX —
        // así se mide la calidad del archivo, no inflada por usernames inexistentes.
        const curPct = foundInDb > 0 ? (withApp / foundInDb) * 100 : 0;
        const prevPct = prevFound > 0 ? (prevWithApp / prevFound) * 100 : 0;
        const pctDelta = prev ? (curPct - prevPct).toFixed(1) : null;
        const pctColor = pctDelta == null ? '#666' : (parseFloat(pctDelta) > 0 ? '#66ff66' : (parseFloat(pctDelta) < 0 ? '#ff8080' : '#666'));
        const pctDeltaStr = pctDelta == null ? '—' : ((parseFloat(pctDelta) > 0 ? '+' : '') + pctDelta + 'pp');
        // Cobertura: % de la base total con app que está en este archivo.
        const coveragePct = baseWithApp > 0 ? ((withApp / baseWithApp) * 100).toFixed(1) : null;
        html += '<tr style="border-bottom:1px solid rgba(255,255,255,0.05);">';
        html += '  <td style="padding:6px 8px;color:#aaa;font-size:11px;white-space:nowrap;">' + escapeHtml(fmtDate(h.at)) + '</td>';
        html += '  <td style="padding:6px 8px;color:#fff;font-weight:600;">' + escapeHtml(h.fileLabel || '—') + fileChangedNote + '</td>';
        html += '  <td style="padding:6px 8px;text-align:right;color:#fff;font-weight:700;">' + fmt(total) + '<br><span style="font-size:10px;font-weight:400;">' + delta(total, prevTotal) + '</span></td>';
        html += '  <td style="padding:6px 8px;text-align:right;color:#7cffb3;font-weight:700;">' + fmt(foundInDb) + '<br><span style="font-size:10px;font-weight:400;">' + delta(foundInDb, prevFound) + '</span></td>';
        html += '  <td style="padding:6px 8px;text-align:right;color:#25d366;font-weight:700;">' + fmt(withApp) + '<br><span style="font-size:10px;font-weight:400;">' + delta(withApp, prevWithApp) + '</span></td>';
        html += '  <td style="padding:6px 8px;text-align:right;color:#fff;">' + curPct.toFixed(1) + '%<br><span style="font-size:10px;color:' + pctColor + ';">' + pctDeltaStr + '</span></td>';
        html += '  <td style="padding:6px 8px;text-align:right;color:#00d4ff;font-weight:700;">' + (coveragePct != null ? coveragePct + '%' : '<span style="color:#666;">—</span>') + '<br><span style="font-size:10px;color:#888;">de tu base</span></td>';
        html += '  <td style="padding:6px 8px;text-align:right;color:#fff;">$' + fmt(h.fileTotalDeposits || 0) + '</td>';
        html += '  <td style="padding:6px 8px;text-align:right;color:#ffd700;">$' + fmt(h.totalRecoverableValue || 0) + '</td>';
        const delBtn = h._id
            ? '<button type="button" onclick="_recontactDeleteHistoryEntry(\'' + escapeHtml(h._id) + '\', \'' + escapeHtml(h.fileLabel || '(sin nombre)') + '\')" title="Borrar esta entrada del historial" style="background:rgba(255,128,128,0.10);border:1px solid rgba(255,128,128,0.40);color:#ff8080;padding:3px 7px;border-radius:5px;cursor:pointer;font-size:11px;">🗑</button>'
            : '<span style="color:#666;" title="Entrada vieja sin id">—</span>';
        html += '  <td style="padding:6px 8px;text-align:center;">' + delBtn + '</td>';
        html += '</tr>';
    }
    html += '    </tbody></table>';
    html += '  </div>';
    // Resumen interpretativo: si los archivos son iguales, calculamos el progreso real total.
    const sameFileSeries = history.filter(h => h.fileLabel === history[0].fileLabel);
    if (sameFileSeries.length >= 2) {
        const newest = sameFileSeries[0];
        const oldest = sameFileSeries[sameFileSeries.length - 1];
        const installs = (newest.withApp || 0) - (oldest.withApp || 0);
        const pctNew = (newest.totalAnalyzed > 0) ? (newest.withApp / newest.totalAnalyzed) * 100 : 0;
        const pctOld = (oldest.totalAnalyzed > 0) ? (oldest.withApp / oldest.totalAnalyzed) * 100 : 0;
        const ppDelta = (pctNew - pctOld).toFixed(1);
        const installsColor = installs > 0 ? '#66ff66' : (installs < 0 ? '#ff8080' : '#bbb');
        html += '<div style="margin-top:10px;padding:8px 12px;background:rgba(102,255,102,0.06);border-left:3px solid #66ff66;border-radius:6px;font-size:12px;color:#fff;">';
        html += '<strong style="color:#66ff66;">📈 Progreso real (mismo archivo "' + escapeHtml(newest.fileLabel || '—') + '"):</strong> entre el ' + escapeHtml(fmtDate(oldest.at)) + ' y el ' + escapeHtml(fmtDate(newest.at)) + ' → <strong style="color:' + installsColor + ';">' + (installs > 0 ? '+' : '') + installs + ' users con app</strong> · ' + pctOld.toFixed(1) + '% → ' + pctNew.toFixed(1) + '% (Δ ' + (ppDelta > 0 ? '+' : '') + ppDelta + 'pp).';
        html += '</div>';
    } else if (history.length >= 2) {
        html += '<div style="margin-top:10px;padding:8px 12px;background:rgba(255,170,68,0.06);border-left:3px solid #ffaa44;border-radius:6px;font-size:12px;color:#ddd;">';
        html += '<strong style="color:#ffaa44;">⚠ Progreso real no calculable:</strong> los análisis tienen archivos distintos. Para ver evolución real, subí siempre el mismo XLSX con los mismos usernames (o exportá uno desde la sección y reusalo).';
        html += '</div>';
    }
    html += '</div>';
    return html;
}

// Sección de mejora archivo-a-archivo: compara items del análisis ACTUAL vs el
// PREVIO (guardado al subir un nuevo XLSX) y lista users que mejoraron entre
// los dos. "Mejora" = instaló app desde la última vez O subió de bucket
// (ej: estaba en 'inactivos' y ahora en 'enRiesgo' o 'calientes').
function _renderRecontactImprovementSection() {
    const cur = _recontactState.items;
    const prev = _recontactState.previousItems;
    const prevSavedAt = _recontactState.previousSavedAt;
    if (!Array.isArray(cur) || !Array.isArray(prev) || prev.length === 0) {
        return '<div style="color:#888;font-size:11px;margin-top:14px;padding:8px 10px;background:rgba(0,0,0,0.20);border-radius:6px;">📊 Subí otro XLSX con fecha distinta para ver acá la mejora vs el análisis anterior.</div>';
    }
    const bucketRank = { inactivos: 0, perdidos: 1, enRiesgo: 2, calientes: 3, '': -1 };
    const prevByName = new Map();
    for (const p of prev) {
        const k = String((p && p.username) || '').toLowerCase();
        if (k) prevByName.set(k, p);
    }
    const installedApp = []; // antes hasApp=false, ahora hasApp=true
    const upBucket = [];     // antes bucket peor, ahora mejor
    for (const c of cur) {
        const k = String((c && c.username) || '').toLowerCase();
        if (!k) continue;
        const p = prevByName.get(k);
        if (!p) continue;
        if (!p.hasApp && c.hasApp) installedApp.push({ username: c.username, prevBucket: p.bucket, curBucket: c.bucket });
        const pr = bucketRank[p.bucket || ''] ?? -1;
        const cr = bucketRank[c.bucket || ''] ?? -1;
        if (pr >= 0 && cr > pr) upBucket.push({ username: c.username, from: p.bucket, to: c.bucket });
    }
    const total = installedApp.length + upBucket.length;
    const fmtDate = (ts) => {
        try { return new Date(ts).toLocaleDateString('es-AR', { day:'2-digit', month:'2-digit', year:'2-digit' }); } catch(_) { return '-'; }
    };
    let html = '<div style="margin-top:14px;background:rgba(102,255,102,0.06);border:1px solid rgba(102,255,102,0.30);border-radius:10px;padding:12px;">';
    html += '  <div style="display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap;gap:6px;margin-bottom:6px;">';
    html += '    <div style="color:#66ff66;font-weight:800;font-size:13px;text-transform:uppercase;letter-spacing:1px;">📈 Mejora vs análisis anterior</div>';
    html += '    <div style="color:#aaa;font-size:11px;">Comparando con el análisis del ' + (prevSavedAt ? fmtDate(prevSavedAt) : '—') + '</div>';
    html += '  </div>';
    if (total === 0) {
        html += '  <div style="color:#888;font-size:12px;padding:6px;">Sin mejoras detectadas entre los dos análisis.</div>';
        html += '</div>';
        return html;
    }
    html += '  <div style="color:#bbb;font-size:11.5px;margin-bottom:8px;">' + total + ' mejoras detectadas — ' + installedApp.length + ' instalaron app, ' + upBucket.length + ' subieron de bucket de actividad</div>';
    if (installedApp.length > 0) {
        html += '  <div style="margin-top:6px;color:#25d366;font-weight:700;font-size:12px;">📱 Instalaron app desde el análisis anterior (' + installedApp.length + '):</div>';
        html += '  <div style="max-height:220px;overflow-y:auto;background:rgba(0,0,0,0.20);border-radius:6px;padding:6px;margin-top:4px;">';
        for (const u of installedApp) {
            html += '<div style="display:flex;justify-content:space-between;color:#fff;font-size:11.5px;padding:3px 6px;border-bottom:1px solid rgba(255,255,255,0.04);"><span><strong>' + escapeHtml(u.username) + '</strong></span><span style="color:#aaa;">' + escapeHtml(u.prevBucket || '—') + ' → ' + escapeHtml(u.curBucket || '—') + '</span></div>';
        }
        html += '  </div>';
    }
    if (upBucket.length > 0) {
        html += '  <div style="margin-top:8px;color:#ffd700;font-weight:700;font-size:12px;">⬆ Subieron de bucket de actividad (' + upBucket.length + '):</div>';
        html += '  <div style="max-height:220px;overflow-y:auto;background:rgba(0,0,0,0.20);border-radius:6px;padding:6px;margin-top:4px;">';
        for (const u of upBucket) {
            html += '<div style="display:flex;justify-content:space-between;color:#fff;font-size:11.5px;padding:3px 6px;border-bottom:1px solid rgba(255,255,255,0.04);"><span><strong>' + escapeHtml(u.username) + '</strong></span><span style="color:#aaa;">' + escapeHtml(u.from || '—') + ' → ' + escapeHtml(u.to || '—') + '</span></div>';
        }
        html += '  </div>';
    }
    html += '</div>';
    return html;
}

function _filterRecontactItems(items, filters) {
    return items.filter(it => {
        if (filters.tier && filters.tier !== 'all' && it.tier !== filters.tier) return false;
        if (filters.bucket && filters.bucket !== 'all' && it.bucket !== filters.bucket) return false;
        if (filters.appStatus === 'with-notifs' && !it.hasNotifs) return false;
        if (filters.appStatus === 'without-app' && it.hasApp) return false;
        if (filters.appStatus === 'app-no-notifs' && !(it.hasApp && !it.hasNotifs)) return false;
        if (filters.line && filters.line !== 'all') {
            if (filters.line === 'no-line') {
                if (it.team || it.linePhone) return false;
            } else {
                const key = (it.team || '') + '||' + (it.linePhone || '');
                if (key !== filters.line) return false;
            }
        }
        return true;
    });
}

function _recontactFilterSet(key, value) {
    if (!window._recontactFilters) window._recontactFilters = {};
    window._recontactFilters[key] = value;
    loadRecontactSection();
}

function _wireRecontactFilters() {
    // El listener Callbell se asigna UNA VEZ a document.body (sobrevive el
    // innerHTML). Acá sólo aseguramos que esté wired y refrescamos el botón.
    _wireRecontactCallbellCheckboxes();
    _updateRecontactSaveButton();
}

// Tarjeta de historial — se muestra en el dashboard (tras hidratar de cache)
// y también como standalone debajo del uploader si el cache expiró.
function _renderRecontactHistoryCard(history) {
    const fmt = n => Number(n || 0).toLocaleString('es-AR');
    let html = '';
    html += '<details ' + (history.length <= 3 ? 'open' : '') + ' style="background:rgba(0,212,255,0.04);border:1px solid rgba(0,212,255,0.20);border-radius:10px;padding:0;margin-bottom:14px;overflow:hidden;">';
    html += '  <summary style="cursor:pointer;padding:10px 14px;background:rgba(0,212,255,0.06);list-style:none;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;">';
    html += '    <span style="color:#00d4ff;font-weight:800;font-size:13px;letter-spacing:0.5px;">📈 HISTORIAL DE ANÁLISIS · ' + history.length + (history.length === 1 ? ' análisis' : ' análisis') + '</span>';
    html += '    <span style="color:#888;font-size:10.5px;">tocá para abrir/cerrar ▾</span>';
    html += '  </summary>';
    html += '  <div style="padding:12px 14px;">';
    html += _renderRecontactHistoryTable(history);
    html += '    <div style="margin-top:8px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;">';
    html += '      <span style="color:#888;font-size:10.5px;">Cada análisis queda guardado por 7 días · máximo ' + RECONTACT_HISTORY_MAX + ' snapshots · los Δ comparan con el análisis anterior.</span>';
    html += '      <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;">';
    // Botón nuevo: matriz de evolución por cohorte. Solo aparece si hay al menos 1 snapshot previo en historial.
    if (history.length >= 2) {
        const prevSnap = history[1] || {};
        const prevIso = prevSnap.at ? new Date(prevSnap.at).toISOString().slice(0, 10) : '';
        html += '        <button type="button" onclick="_recontactOpenCohortEvolution(\'' + escapeHtml(prevIso) + '\')" title="Compara qué bucket tenía cada user en una fecha pasada vs ahora — sin depender de qué XLSX subiste" style="padding:5px 11px;font-size:11px;background:rgba(0,212,255,0.10);border:1px solid rgba(0,212,255,0.45);color:#00d4ff;border-radius:5px;cursor:pointer;font-weight:700;">🔬 Comparar evolución vs análisis anterior</button>';
    }
    html += '        <button type="button" onclick="_recontactClearHistory()" style="padding:4px 9px;font-size:10.5px;background:rgba(255,80,80,0.10);border:1px solid rgba(255,80,80,0.30);color:#ff8080;border-radius:5px;cursor:pointer;">🗑 Borrar historial</button>';
    html += '      </div>';
    html += '    </div>';
    html += '  </div>';
    html += '</details>';
    return html;
}

function _renderRecontactHistoryStandalone(history) {
    let html = '';
    html += '<div style="margin-top:14px;background:rgba(0,212,255,0.04);border:1px solid rgba(0,212,255,0.20);border-radius:10px;padding:14px;">';
    html += '  <div style="color:#00d4ff;font-weight:800;font-size:13px;letter-spacing:0.5px;margin-bottom:8px;">📈 HISTORIAL DE ANÁLISIS PREVIOS</div>';
    html += '  <div style="color:#aaa;font-size:11.5px;margin-bottom:10px;">El cache expiró pero el historial sigue guardado. Subí un archivo nuevo arriba para ver el panorama actualizado.</div>';
    html += _renderRecontactHistoryTable(history);
    html += '  <div style="margin-top:8px;text-align:right;">';
    html += '    <button type="button" onclick="_recontactClearHistory()" style="padding:4px 9px;font-size:10.5px;background:rgba(255,80,80,0.10);border:1px solid rgba(255,80,80,0.30);color:#ff8080;border-radius:5px;cursor:pointer;">🗑 Borrar historial</button>';
    html += '  </div>';
    html += '</div>';
    return html;
}

// Calcula duración legible: "3 d 4 h" / "12 h" / "45 min"
function _recontactFormatDuration(ms) {
    if (ms == null || ms < 0) return '';
    const min = Math.round(ms / 60000);
    if (min < 60) return min + ' min';
    const h = Math.floor(min / 60);
    if (h < 24) {
        const remMin = min - h * 60;
        return h + ' h' + (remMin > 0 ? ' ' + remMin + ' min' : '');
    }
    const d = Math.floor(h / 24);
    const remH = h - d * 24;
    return d + ' d' + (remH > 0 ? ' ' + remH + ' h' : '');
}

// Tabla del historial: una fila por snapshot, con deltas entre snapshots.
function _renderRecontactHistoryTable(history) {
    const fmt = n => Number(n || 0).toLocaleString('es-AR');
    const delta = (cur, prev) => {
        if (prev == null) return '';
        const d = (cur || 0) - (prev || 0);
        if (d === 0) return ' <span style="color:#666;">·</span>';
        const sign = d > 0 ? '+' : '';
        return ' <span style="color:' + (d > 0 ? '#66ff66' : '#ff8080') + ';font-size:9.5px;">' + sign + fmt(d) + '</span>';
    };
    let html = '';
    html += '<div style="overflow-x:auto;max-height:260px;overflow-y:auto;">';
    html += '<table style="width:100%;border-collapse:collapse;font-size:11px;min-width:820px;">';
    html += '  <thead><tr style="background:rgba(255,255,255,0.04);position:sticky;top:0;">';
    html += '    <th style="text-align:left;padding:6px 8px;color:#aaa;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">Cuándo</th>';
    html += '    <th style="text-align:left;padding:6px 8px;color:#66ff66;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;" title="Tiempo que estuvo activo este análisis hasta ser reemplazado por el siguiente">⏱ Vigente</th>';
    html += '    <th style="text-align:left;padding:6px 8px;color:#aaa;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">Archivo</th>';
    html += '    <th style="text-align:right;padding:6px 8px;color:#aaa;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;">Total</th>';
    html += '    <th style="text-align:right;padding:6px 8px;color:#ff5050;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;" title="0-10 días sin cargar">🔥 Cal.</th>';
    html += '    <th style="text-align:right;padding:6px 8px;color:#ffaa44;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;" title="10-20 días">⚠ Riesgo</th>';
    html += '    <th style="text-align:right;padding:6px 8px;color:#9b30ff;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;" title="20-30 días">💔 Perd.</th>';
    html += '    <th style="text-align:right;padding:6px 8px;color:#888;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;" title="+30 días">☠ Inact.</th>';
    html += '    <th style="text-align:right;padding:6px 8px;color:#7cffb3;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;" title="total con app instalada (sin importar notifs)">📱 Con app</th>';
    html += '    <th style="text-align:right;padding:6px 8px;color:#25d366;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;" title="con app + notifs (push directo)">🔔 Push</th>';
    html += '    <th style="text-align:right;padding:6px 8px;color:#00d4ff;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;" title="sin app (recontacto sólo por WhatsApp)">💬 WA</th>';
    html += '    <th style="text-align:right;padding:6px 8px;color:#ffd700;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;" title="sin línea asignada en Equipos">⚠ Sin línea</th>';
    html += '    <th style="text-align:right;padding:6px 8px;color:#aaa;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;" title="$ cargas del archivo">$ Archivo</th>';
    html += '    <th style="text-align:center;padding:6px 8px;color:#ff8080;border-bottom:1px solid rgba(255,255,255,0.10);font-weight:600;" title="Borrar esta entrada">🗑</th>';
    html += '  </tr></thead><tbody>';
    for (let i = 0; i < history.length; i++) {
        const s = history[i];
        const prev = history[i + 1] || null; // siguiente en la lista = más viejo
        const next = i > 0 ? history[i - 1] : null; // anterior en la lista = más reciente que este
        const dt = new Date(s.at);
        const dateStr = dt.toLocaleDateString('es-AR', { day: '2-digit', month: '2-digit' }) + ' ' + dt.toLocaleTimeString('es-AR', { hour: '2-digit', minute: '2-digit' });
        const rel = _recontactRelTime(s.at);
        const lbl = s.label || '<span style="color:#666;">(sin nombre)</span>';
        const b  = s.buckets || {};
        const pb = prev ? (prev.buckets || {}) : {};
        const isFirst = i === 0;
        // Duración: si hay un análisis posterior, fue desde s.at hasta next.at.
        // Si es el más reciente (i===0), está vigente hasta ahora.
        const endTime = next ? next.at : Date.now();
        const durationMs = endTime - s.at;
        const durationStr = _recontactFormatDuration(durationMs);
        const durationCell = isFirst
            ? '<span style="color:#66ff66;font-weight:700;">' + durationStr + '</span><br><span style="color:#66ff66;font-size:9.5px;">● ACTUAL</span>'
            : '<span style="color:#bbb;">' + durationStr + '</span>';
        html += '<tr style="border-bottom:1px solid rgba(255,255,255,0.04);' + (isFirst ? 'background:rgba(102,255,102,0.04);' : '') + '">';
        html += '  <td style="padding:5px 8px;color:#fff;font-size:10.5px;">' + dateStr + '<br><span style="color:#888;font-size:9.5px;">' + rel + '</span></td>';
        html += '  <td style="padding:5px 8px;font-size:10.5px;">' + durationCell + '</td>';
        html += '  <td style="padding:5px 8px;color:#bbb;font-size:10.5px;max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="' + escapeHtml(s.label || '') + '">' + escapeHtml(s.label ? (s.label.length > 22 ? s.label.slice(0, 22) + '…' : s.label) : '(sin nombre)') + '</td>';
        html += '  <td style="padding:5px 8px;text-align:right;color:#fff;font-weight:700;">' + fmt(s.totalAnalyzed) + delta(s.totalAnalyzed, prev && prev.totalAnalyzed) + '</td>';
        html += '  <td style="padding:5px 8px;text-align:right;color:#ff5050;">' + fmt(b.calientes || 0) + delta(b.calientes, pb.calientes) + '</td>';
        html += '  <td style="padding:5px 8px;text-align:right;color:#ffaa44;">' + fmt(b.enRiesgo || 0)  + delta(b.enRiesgo, pb.enRiesgo) + '</td>';
        html += '  <td style="padding:5px 8px;text-align:right;color:#9b30ff;">' + fmt(b.perdidos || 0)  + delta(b.perdidos, pb.perdidos) + '</td>';
        html += '  <td style="padding:5px 8px;text-align:right;color:#888;">'    + fmt(b.inactivos || 0) + delta(b.inactivos, pb.inactivos) + '</td>';
        html += '  <td style="padding:5px 8px;text-align:right;color:#7cffb3;font-weight:600;">' + fmt(s.withApp || 0) + delta(s.withApp, prev && prev.withApp) + '</td>';
        html += '  <td style="padding:5px 8px;text-align:right;color:#25d366;">' + fmt(s.withNotifs || 0) + delta(s.withNotifs, prev && prev.withNotifs) + '</td>';
        html += '  <td style="padding:5px 8px;text-align:right;color:#00d4ff;">' + fmt(s.withoutApp || 0) + delta(s.withoutApp, prev && prev.withoutApp) + '</td>';
        html += '  <td style="padding:5px 8px;text-align:right;color:#ffd700;">' + fmt(s.sinLinea || 0)   + delta(s.sinLinea, prev && prev.sinLinea) + '</td>';
        html += '  <td style="padding:5px 8px;text-align:right;color:#bbb;font-family:monospace;font-size:10.5px;">' + (s.fileTotalDeposits ? '$' + fmt(s.fileTotalDeposits) : '—') + '</td>';
        const delBtn = s._id
            ? '<button type="button" onclick="_recontactDeleteHistoryEntry(\'' + escapeHtml(s._id) + '\', \'' + escapeHtml(s.label || '(sin nombre)') + '\')" title="Borrar esta entrada del historial" style="background:rgba(255,128,128,0.10);border:1px solid rgba(255,128,128,0.40);color:#ff8080;padding:3px 7px;border-radius:5px;cursor:pointer;font-size:11px;">🗑</button>'
            : '<span style="color:#666;" title="Entrada vieja sin id">—</span>';
        html += '  <td style="padding:5px 8px;text-align:center;">' + delBtn + '</td>';
        html += '</tr>';
    }
    html += '</tbody></table></div>';
    return html;
}

// Borra una entrada del historial por su _id (server) y recarga la lista.
// Saca a un usuario de la lista de Post recontactación. NO borra su tag
// de Callbell — solo limpia los campos convertedAt/convertedBy en el server
// para que el filtro convertedAt:{$ne:null} ya no lo agarre. Idempotente.
async function _recontactDeleteConversion(username) {
    if (!username) return;
    if (!confirm('¿Sacar a "' + username + '" de la lista de Post recontactación?\n\nSu etiqueta de Callbell queda intacta — solo se saca de esta vista.')) return;
    try {
        const r = await authFetch('/api/admin/callbell/conversions/' + encodeURIComponent(username), { method: 'DELETE' });
        const d = await r.json();
        if (!r.ok) {
            showToast('❌ ' + (d.error || 'Error al borrar'), 'error');
            return;
        }
        showToast('✅ ' + username + ' sacado de la lista', 'success');
        // Invalidar cache + refresh
        _recontactConversionsCache = null;
        loadRecontactConversions();
    } catch (e) {
        showToast('Error de conexión', 'error');
    }
}

async function _recontactDeleteHistoryEntry(id, label) {
    if (!id) { showToast('ID inválido', 'error'); return; }
    if (!confirm('¿Borrar la entrada del historial "' + (label || '(sin nombre)') + '"?\n\nNo se puede deshacer.')) return;
    try {
        const r = await authFetch('/api/admin/recontact/history/' + encodeURIComponent(id), { method: 'DELETE' });
        const d = await r.json();
        if (!r.ok) {
            showToast('❌ ' + (d.error || 'Error al borrar'), 'error');
            return;
        }
        showToast('✅ Entrada borrada', 'success');
        // Refrescar cache + UI en las 2 secciones (recontactación y post-recontactación).
        try {
            _recontactHistoryCache = null;
            localStorage.removeItem(RECONTACT_HISTORY_KEY);
        } catch (_) {}
        await _recontactRefreshHistory().catch(() => {});
        // Re-render según la sección activa.
        const recSec = document.getElementById('recontactSection');
        if (recSec && recSec.classList.contains('active')) {
            loadRecontactSection();
        }
        const postSec = document.getElementById('recontactConversionsSection');
        if (postSec && postSec.classList.contains('active')) {
            loadRecontactConversions();
        }
    } catch (e) {
        showToast('Error de conexión', 'error');
    }
}

// === Cohort Evolution Modal ===
// Compara el bucket de actividad de cada usuario en una fecha pasada vs AHORA.
// A diferencia del delta de la tabla del historial (que depende del XLSX),
// este análisis usa el historial de transacciones reales del server — los
// nros son verdaderos independientemente de qué archivo subiste.
async function _recontactOpenCohortEvolution(defaultPrevDate) {
    // Crear modal
    let modal = document.getElementById('cohortEvolutionModal');
    if (modal) modal.remove();
    modal = document.createElement('div');
    modal.id = 'cohortEvolutionModal';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.85);z-index:9999;display:flex;align-items:flex-start;justify-content:center;padding:30px 14px;overflow-y:auto;';
    modal.innerHTML = '<div style="background:#0a1428;border:1px solid rgba(0,212,255,0.40);border-radius:12px;max-width:1100px;width:100%;padding:18px 20px;color:#fff;box-shadow:0 12px 40px rgba(0,212,255,0.15);">' +
        '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;gap:10px;flex-wrap:wrap;">' +
        '  <div><h3 style="margin:0;color:#00d4ff;font-size:17px;">🔬 Evolución de cohortes — del análisis anterior a HOY</h3><div style="color:#888;font-size:11.5px;margin-top:2px;">Mide cómo cambió la actividad real de cada usuario entre 2 fechas. Independiente del XLSX subido.</div></div>' +
        '  <button type="button" onclick="document.getElementById(\'cohortEvolutionModal\').remove()" style="background:rgba(255,80,80,0.15);border:1px solid rgba(255,80,80,0.40);color:#ff8080;padding:5px 11px;border-radius:6px;cursor:pointer;font-weight:700;">✕</button>' +
        '</div>' +
        '<div style="background:rgba(0,212,255,0.05);border:1px solid rgba(0,212,255,0.20);border-radius:8px;padding:10px 12px;margin-bottom:12px;">' +
        '  <div style="display:flex;gap:14px;align-items:center;flex-wrap:wrap;">' +
        '    <label style="color:#bbb;font-size:12px;">Fecha de comparación: ' +
        '      <input type="date" id="cohortPrevDate" value="' + (defaultPrevDate || '') + '" style="background:#0d1828;color:#fff;border:1px solid rgba(0,212,255,0.35);padding:5px 8px;border-radius:5px;font-family:inherit;font-size:12px;margin-left:6px;">' +
        '    </label>' +
        '    <button type="button" onclick="_recontactRunCohortEvolution()" style="padding:6px 14px;background:linear-gradient(135deg,#00d4ff,#0080a0);color:#fff;border:none;border-radius:6px;font-weight:700;cursor:pointer;font-size:12px;">▶ Calcular</button>' +
        '    <span style="color:#888;font-size:11px;">El cálculo escanea la tabla de movimientos reales · puede tardar 5-30s con 25k users</span>' +
        '  </div>' +
        '</div>' +
        '<div id="cohortEvolutionResult" style="color:#888;text-align:center;padding:30px;font-size:13px;">Elegí la fecha de comparación y tocá Calcular.</div>' +
        '</div>';
    document.body.appendChild(modal);
    modal.addEventListener('click', e => { if (e.target === modal) modal.remove(); });
    // Auto-run si tenemos default.
    if (defaultPrevDate) _recontactRunCohortEvolution();
}

async function _recontactRunCohortEvolution() {
    const inp = document.getElementById('cohortPrevDate');
    const resBox = document.getElementById('cohortEvolutionResult');
    if (!inp || !resBox) return;
    const prevDate = inp.value;
    if (!prevDate) { showToast('Elegí fecha de comparación', 'warning'); return; }
    resBox.innerHTML = '<div style="color:#00d4ff;padding:30px;text-align:center;font-size:13px;">⏳ Calculando matriz de evolución… (puede tardar hasta 30s)</div>';
    try {
        const r = await authFetch('/api/admin/recontact/cohort-evolution?prevDate=' + encodeURIComponent(prevDate));
        const d = await r.json();
        if (!r.ok) {
            resBox.innerHTML = '<div style="color:#ff8080;padding:20px;text-align:center;">❌ ' + escapeHtml(d.error || 'Error') + '</div>';
            return;
        }
        resBox.innerHTML = _renderCohortEvolution(d);
    } catch (e) {
        resBox.innerHTML = '<div style="color:#ff8080;padding:20px;text-align:center;">❌ Error de conexión: ' + escapeHtml(e.message || String(e)) + '</div>';
    }
}

function _renderCohortEvolution(d) {
    const fmt = n => Number(n || 0).toLocaleString('es-AR');
    const t = d.totals || {};
    const m = d.matrix || {};
    const tr = d.transitions || {};

    const bucketDef = {
        calientes: { label: '🔥 CAL', color: '#ff5050' },
        enRiesgo:  { label: '⚠ RIESGO', color: '#ffaa44' },
        perdidos:  { label: '💔 PERD', color: '#9b30ff' },
        inactivos: { label: '☠ INACT', color: '#888' },
        noDeposit: { label: '— sin dep', color: '#555' }
    };
    const buckets = ['calientes', 'enRiesgo', 'perdidos', 'inactivos', 'noDeposit'];

    // KPIs principales.
    const netColor = t.netCalientesChange > 0 ? '#66ff66' : (t.netCalientesChange < 0 ? '#ff8080' : '#bbb');
    const netSign = t.netCalientesChange > 0 ? '+' : '';
    let html = '<div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(150px, 1fr));gap:10px;margin-bottom:14px;">';
    html += _cohortKpi('🔥 Calientes ' + (d.prevDate || 'antes'), fmt(t.prevCalientes), '#ff5050');
    html += _cohortKpi('🔥 Calientes HOY', fmt(t.curCalientes), '#ff5050', (netSign + fmt(t.netCalientesChange)), netColor);
    html += _cohortKpi('✅ Retenidos (CAL→CAL)', fmt(t.retained), '#66ff66', 'siguen calientes');
    html += _cohortKpi('❄ Se enfriaron', fmt(t.cooled), '#ff8080', 'eran cal — bajaron');
    html += _cohortKpi('💪 Recuperados', fmt(t.recovered), '#25d366', 'no eran cal → ahora sí');
    html += _cohortKpi('✨ Nuevos depositantes', fmt(t.brandNew), '#ffd700', 'primera carga después');
    html += '</div>';

    // Matriz cross-tab.
    html += '<div style="background:rgba(0,212,255,0.04);border:1px solid rgba(0,212,255,0.20);border-radius:10px;padding:14px;margin-bottom:14px;">';
    html += '  <div style="color:#00d4ff;font-weight:800;font-size:13px;margin-bottom:4px;">📊 Matriz: bucket EL ' + escapeHtml(d.prevDate) + ' → bucket HOY (' + (d.daysBetween || 0) + ' días)</div>';
    html += '  <div style="color:#888;font-size:11px;margin-bottom:10px;">Filas = estado en el pasado · columnas = estado actual. Verde = sin movimiento (diagonal) o mejor. Rojo = peor.</div>';
    html += '  <table style="width:100%;border-collapse:collapse;font-size:11.5px;">';
    html += '    <thead><tr>';
    html += '      <th style="text-align:left;padding:7px 8px;color:#888;border-bottom:1px solid rgba(255,255,255,0.10);">↓ ' + escapeHtml(d.prevDate) + ' \\ HOY →</th>';
    for (const c of buckets) {
        html += '      <th style="text-align:right;padding:7px 8px;color:' + bucketDef[c].color + ';border-bottom:1px solid rgba(255,255,255,0.10);font-weight:700;">' + bucketDef[c].label + '</th>';
    }
    html += '      <th style="text-align:right;padding:7px 8px;color:#fff;border-bottom:1px solid rgba(255,255,255,0.10);">total</th>';
    html += '    </tr></thead><tbody>';
    const bucketRank = { calientes: 3, enRiesgo: 2, perdidos: 1, inactivos: 0, noDeposit: -1 };
    for (const p of buckets) {
        const rowTotal = buckets.reduce((s, c) => s + (m[p] && m[p][c] || 0), 0);
        html += '<tr style="border-bottom:1px solid rgba(255,255,255,0.04);">';
        html += '  <td style="padding:6px 8px;color:' + bucketDef[p].color + ';font-weight:700;">' + bucketDef[p].label + '</td>';
        for (const c of buckets) {
            const v = m[p] && m[p][c] || 0;
            const isDiag = p === c;
            const pr = bucketRank[p], cr = bucketRank[c];
            let cellColor = '#fff';
            let bg = 'transparent';
            if (v > 0) {
                if (isDiag) { cellColor = '#bbb'; bg = 'rgba(255,255,255,0.04)'; }
                else if (cr > pr) { cellColor = '#66ff66'; bg = 'rgba(102,255,102,0.08)'; }
                else if (cr < pr) { cellColor = '#ff8080'; bg = 'rgba(255,128,128,0.06)'; }
            } else {
                cellColor = '#444';
            }
            html += '<td style="padding:6px 8px;text-align:right;color:' + cellColor + ';background:' + bg + ';font-weight:' + (v > 0 ? '700' : '400') + ';">' + fmt(v) + '</td>';
        }
        html += '<td style="padding:6px 8px;text-align:right;color:#fff;font-weight:700;">' + fmt(rowTotal) + '</td>';
        html += '</tr>';
    }
    // Fila de totales por columna.
    html += '<tr style="border-top:2px solid rgba(0,212,255,0.30);">';
    html += '  <td style="padding:6px 8px;color:#00d4ff;font-weight:800;">total HOY</td>';
    for (const c of buckets) {
        const colTotal = buckets.reduce((s, p) => s + (m[p] && m[p][c] || 0), 0);
        html += '<td style="padding:6px 8px;text-align:right;color:#fff;font-weight:800;">' + fmt(colTotal) + '</td>';
    }
    html += '<td style="padding:6px 8px;text-align:right;color:#00d4ff;font-weight:800;">' + fmt(t.analyzedItems) + '</td>';
    html += '</tr>';
    html += '  </tbody></table>';
    html += '</div>';

    // Listas clave de transiciones.
    const sections = [
        { key: 'retainedHot', label: '🔥 Siguen calientes (CAL → CAL)', color: '#66ff66', tip: 'Los más valiosos: cargaron antes y siguieron cargando.' },
        { key: 'recoveredFromInact', label: '💪 RECUPERADOS de inactivo → caliente', color: '#25d366', tip: 'Métrica directa de tu trabajo de recontacto. Volvieron a cargar después de 30+ días.' },
        { key: 'recoveredFromPerd', label: '💪 Recuperados de perdido → caliente', color: '#25d366', tip: 'Estaban entre 20-30 días sin cargar y volvieron.' },
        { key: 'recoveredFromRisk', label: '💪 Recuperados de riesgo → caliente', color: '#25d366', tip: 'Estaban entre 10-20 días sin cargar y volvieron.' },
        { key: 'cooledHotToRisk', label: '❄ Se enfriaron a riesgo (CAL → RIESGO)', color: '#ffaa44', tip: 'Aún recuperables — están al borde, mandales un WhatsApp.' },
        { key: 'cooledHotToPerd', label: '❄ Se enfriaron a perdidos (CAL → PERD)', color: '#9b30ff', tip: 'Necesitan más esfuerzo para recuperarlos.' },
        { key: 'cooledHotToInact', label: '☠ Se perdieron (CAL → INACTIVOS)', color: '#ff5050', tip: 'Eran calientes y ahora no cargan hace 30+ días. Alta señal de pérdida.' },
        { key: 'newDepositors', label: '✨ Cargaron por primera vez (después de ' + d.prevDate + ')', color: '#ffd700', tip: 'No tenían cargas antes de esta fecha. Son ventas nuevas reales.' }
    ];
    for (const sec of sections) {
        const arr = tr[sec.key] || [];
        if (arr.length === 0) continue;
        html += '<details style="background:rgba(0,0,0,0.20);border:1px solid rgba(255,255,255,0.08);border-radius:8px;padding:0;margin-bottom:8px;">';
        html += '  <summary style="cursor:pointer;padding:9px 13px;list-style:none;display:flex;justify-content:space-between;align-items:center;gap:8px;">';
        html += '    <span style="color:' + sec.color + ';font-weight:700;font-size:12.5px;">' + sec.label + ' · ' + fmt(arr.length) + (arr.length >= 300 ? '+' : '') + '</span>';
        html += '    <span style="color:#888;font-size:10.5px;">tocá para abrir ▾</span>';
        html += '  </summary>';
        html += '  <div style="padding:8px 13px 12px;">';
        html += '    <div style="color:#bbb;font-size:11px;margin-bottom:8px;">' + sec.tip + '</div>';
        html += '    <div style="max-height:260px;overflow-y:auto;background:rgba(0,0,0,0.30);border-radius:6px;padding:6px;">';
        html += '      <table style="width:100%;font-size:11px;border-collapse:collapse;">';
        html += '        <thead><tr style="color:#aaa;border-bottom:1px solid rgba(255,255,255,0.06);"><th style="text-align:left;padding:4px 6px;">Usuario</th><th style="text-align:left;padding:4px 6px;">Equipo</th><th style="text-align:right;padding:4px 6px;">Días antes</th><th style="text-align:right;padding:4px 6px;">Días hoy</th><th style="text-align:center;padding:4px 6px;">App</th></tr></thead>';
        html += '        <tbody>';
        for (const u of arr) {
            html += '<tr style="border-bottom:1px solid rgba(255,255,255,0.03);">';
            html += '  <td style="padding:4px 6px;color:#fff;font-weight:600;">' + escapeHtml(u.username || '—') + '</td>';
            html += '  <td style="padding:4px 6px;color:#bbb;">' + escapeHtml(u.team || '—') + '</td>';
            html += '  <td style="padding:4px 6px;text-align:right;color:#888;">' + (u.prevDaysSince == null ? '—' : u.prevDaysSince + 'd') + '</td>';
            html += '  <td style="padding:4px 6px;text-align:right;color:#fff;">' + (u.curDaysSince == null ? '—' : u.curDaysSince + 'd') + '</td>';
            html += '  <td style="padding:4px 6px;text-align:center;">' + (u.hasApp ? '<span style="color:#25d366;">📱</span>' : '<span style="color:#666;">—</span>') + '</td>';
            html += '</tr>';
        }
        html += '        </tbody></table>';
        html += '    </div>';
        // Exportar a CSV
        html += '    <div style="margin-top:6px;text-align:right;">';
        html += '      <button type="button" onclick="_cohortExportTransition(\'' + sec.key + '\')" style="padding:3px 9px;font-size:10.5px;background:rgba(0,212,255,0.10);border:1px solid rgba(0,212,255,0.35);color:#00d4ff;border-radius:5px;cursor:pointer;">📥 Exportar CSV</button>';
        html += '    </div>';
        html += '  </div>';
        html += '</details>';
    }

    // Stash data for export.
    window._lastCohortEvolutionData = d;

    return html;
}

function _cohortKpi(label, value, color, sub, subColor) {
    let html = '<div style="background:rgba(0,0,0,0.30);border:1px solid rgba(255,255,255,0.08);border-radius:8px;padding:10px 12px;">';
    html += '<div style="color:#888;font-size:11px;text-transform:uppercase;letter-spacing:0.5px;">' + label + '</div>';
    html += '<div style="color:' + (color || '#fff') + ';font-size:20px;font-weight:800;margin-top:2px;">' + value + '</div>';
    if (sub) html += '<div style="color:' + (subColor || '#888') + ';font-size:10.5px;margin-top:1px;">' + sub + '</div>';
    html += '</div>';
    return html;
}

function _cohortExportTransition(key) {
    const d = window._lastCohortEvolutionData;
    if (!d || !d.transitions || !d.transitions[key]) { showToast('No hay datos para exportar', 'warning'); return; }
    const arr = d.transitions[key];
    const rows = [['username', 'team', 'prev_bucket', 'cur_bucket', 'prev_days', 'cur_days', 'has_app', 'last_deposit_at']];
    for (const u of arr) {
        rows.push([u.username || '', u.team || '', u.prevBucket || '', u.curBucket || '', u.prevDaysSince == null ? '' : u.prevDaysSince, u.curDaysSince == null ? '' : u.curDaysSince, u.hasApp ? 'si' : 'no', u.lastDepositAt || '']);
    }
    const csv = rows.map(r => r.map(c => '"' + String(c).replace(/"/g, '""') + '"').join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'cohort-evolution-' + key + '-' + (d.prevDate || 'prev') + '-to-hoy.csv';
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 100);
    showToast('✅ CSV exportado · ' + arr.length + ' filas', 'success');
}

// Matriz panorama: bucket de actividad × estado de app/notifs.
// Cada celda muestra cantidad + suma de cargas del archivo (si las hay) y
// es clickable para filtrar la tabla. La fila "Sin línea asignada" debajo
// te avisa cuántos no tienen equipo/línea para derivar al WhatsApp.
function _renderRecontactPanorama(items, currentFilters) {
    const fmt = n => Number(n || 0).toLocaleString('es-AR');
    // Agrupar
    const buckets = ['calientes', 'enRiesgo', 'perdidos', 'inactivos'];
    const bucketDef = {
        calientes: { label: '🔥 Calientes',   sub: '0-10 días',   color: '#ff5050' },
        enRiesgo:  { label: '⚠ En riesgo',    sub: '10-20 días',  color: '#ffaa44' },
        perdidos:  { label: '💔 Perdidos',    sub: '20-30 días',  color: '#9b30ff' },
        inactivos: { label: '☠ Inactivos',    sub: '+30 días',    color: '#888' }
    };
    const cols = [
        { k: 'with-notifs',   label: '📱 Push directo',  sub: 'app+notifs',     color: '#25d366' },
        { k: 'app-no-notifs', label: '🔕 App sin notifs', sub: 'reactivar',      color: '#ffaa44' },
        { k: 'without-app',   label: '💬 Sin app (WA)',  sub: 'WhatsApp',       color: '#00d4ff' }
    ];

    // matriz[bucket][col.k] = { count, sumCargas, sumNeto, sinLinea }
    const matrix = {};
    for (const b of buckets) {
        matrix[b] = {};
        for (const c of cols) matrix[b][c.k] = { count: 0, sumCargas: 0, sumNeto: 0, sinLinea: 0 };
    }
    let sinLineaTotal = 0, sinLineaSinApp = 0;
    const rowTotals = {};
    const colTotals = {};
    for (const c of cols) colTotals[c.k] = { count: 0, sumCargas: 0, sumNeto: 0, sinLinea: 0 };
    for (const b of buckets) rowTotals[b] = { count: 0, sumCargas: 0, sumNeto: 0, sinLinea: 0 };
    let grandTotal = { count: 0, sumCargas: 0, sumNeto: 0, sinLinea: 0 };

    const colKeyFor = (it) => {
        if (it.hasApp && it.hasNotifs) return 'with-notifs';
        if (it.hasApp && !it.hasNotifs) return 'app-no-notifs';
        return 'without-app';
    };

    for (const it of items) {
        const b = buckets.includes(it.bucket) ? it.bucket : 'inactivos';
        const ck = colKeyFor(it);
        const cell = matrix[b][ck];
        cell.count++;
        cell.sumCargas += Number(it.fileDeposits || 0);
        cell.sumNeto   += Number(it.fileNet || 0);
        const noLine = !it.team && !it.linePhone;
        if (noLine) cell.sinLinea++;
        rowTotals[b].count++;
        rowTotals[b].sumCargas += Number(it.fileDeposits || 0);
        rowTotals[b].sumNeto += Number(it.fileNet || 0);
        if (noLine) rowTotals[b].sinLinea++;
        colTotals[ck].count++;
        colTotals[ck].sumCargas += Number(it.fileDeposits || 0);
        colTotals[ck].sumNeto += Number(it.fileNet || 0);
        if (noLine) colTotals[ck].sinLinea++;
        grandTotal.count++;
        grandTotal.sumCargas += Number(it.fileDeposits || 0);
        grandTotal.sumNeto += Number(it.fileNet || 0);
        if (noLine) {
            grandTotal.sinLinea++;
            sinLineaTotal++;
            if (!it.hasApp) sinLineaSinApp++;
        }
    }

    const hasFileTx = grandTotal.sumCargas > 0;
    const hasSinLinea = sinLineaTotal > 0;
    const f = currentFilters || { tier: 'all', bucket: 'all', appStatus: 'all' };

    let html = '';
    html += '<div style="background:linear-gradient(135deg,rgba(0,212,255,0.06),rgba(0,128,255,0.04));border:1px solid rgba(0,212,255,0.30);border-radius:12px;padding:14px;margin-bottom:14px;">';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;margin-bottom:10px;">';
    html += '<div><div style="color:#00d4ff;font-weight:800;font-size:13px;text-transform:uppercase;letter-spacing:1px;">📊 PANORAMA — bucket × estado de app</div>';
    html += '<div style="color:#aaa;font-size:11px;margin-top:2px;">Tocá una celda para filtrar la tabla de abajo. Filas = días sin cargar · Columnas = canal disponible.</div></div>';
    if (f.bucket !== 'all' || f.appStatus !== 'all') {
        html += '<button type="button" onclick="_recontactFilterClear()" style="padding:5px 10px;font-size:11px;background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.20);color:#fff;border-radius:6px;cursor:pointer;">✕ Limpiar filtro</button>';
    }
    html += '</div>';

    html += '<div style="overflow-x:auto;">';
    html += '<table style="width:100%;border-collapse:separate;border-spacing:4px;font-size:11.5px;min-width:680px;">';
    // Header row
    html += '<thead><tr>';
    html += '<th style="padding:6px;text-align:left;color:#888;font-weight:600;font-size:10.5px;letter-spacing:0.5px;"></th>';
    for (const c of cols) {
        html += '<th style="padding:6px 8px;text-align:center;color:' + c.color + ';font-weight:800;font-size:11.5px;background:rgba(255,255,255,0.02);border-radius:6px;">' + c.label + '<br><span style="color:#888;font-size:9.5px;font-weight:400;">' + c.sub + '</span></th>';
    }
    html += '<th style="padding:6px 8px;text-align:center;color:#fff;font-weight:800;font-size:11.5px;background:rgba(255,255,255,0.06);border-radius:6px;">TOTAL</th>';
    html += '</tr></thead>';
    html += '<tbody>';
    for (const b of buckets) {
        const bd = bucketDef[b];
        html += '<tr>';
        html += '<td style="padding:6px 8px;color:' + bd.color + ';font-weight:800;background:rgba(255,255,255,0.02);border-radius:6px;">' + bd.label + '<br><span style="color:#888;font-size:9.5px;font-weight:400;">' + bd.sub + '</span></td>';
        for (const c of cols) {
            const cell = matrix[b][c.k];
            const isActive = f.bucket === b && f.appStatus === c.k;
            const dim = (f.bucket !== 'all' && f.bucket !== b) || (f.appStatus !== 'all' && f.appStatus !== c.k);
            const bg = isActive ? 'rgba(255,215,0,0.12)' : (cell.count === 0 ? 'rgba(0,0,0,0.20)' : 'rgba(' + _hexToRgb(c.color) + ',0.08)');
            const border = isActive ? '2px solid #ffd700' : '1px solid rgba(255,255,255,0.06)';
            const opac = dim ? '0.45' : '1';
            html += '<td onclick="_recontactSetCellFilter(\'' + b + '\',\'' + c.k + '\')" style="cursor:pointer;padding:8px;text-align:center;background:' + bg + ';border:' + border + ';border-radius:6px;opacity:' + opac + ';transition:all 0.15s ease;" title="Filtrar a ' + bd.label + ' + ' + c.label + '">';
            html += '<div style="color:#fff;font-size:18px;font-weight:900;line-height:1;">' + fmt(cell.count) + '</div>';
            if (hasFileTx && cell.sumCargas > 0) {
                html += '<div style="color:#25d366;font-size:10px;margin-top:3px;font-family:monospace;">$' + fmt(cell.sumCargas) + '</div>';
            }
            if (cell.sinLinea > 0) {
                html += '<div style="color:#ff8080;font-size:9.5px;margin-top:2px;">⚠ ' + cell.sinLinea + ' sin línea</div>';
            }
            html += '</td>';
        }
        // Total fila
        const rt = rowTotals[b];
        html += '<td style="padding:8px;text-align:center;background:rgba(255,255,255,0.06);border-radius:6px;">';
        html += '<div style="color:#fff;font-size:18px;font-weight:900;line-height:1;">' + fmt(rt.count) + '</div>';
        if (hasFileTx && rt.sumCargas > 0) html += '<div style="color:#25d366;font-size:10px;margin-top:3px;font-family:monospace;">$' + fmt(rt.sumCargas) + '</div>';
        if (rt.sinLinea > 0) html += '<div style="color:#ff8080;font-size:9.5px;margin-top:2px;">⚠ ' + rt.sinLinea + '</div>';
        html += '</td>';
        html += '</tr>';
    }
    // Total row
    html += '<tr>';
    html += '<td style="padding:8px;text-align:left;color:#fff;font-weight:800;font-size:12px;background:rgba(255,255,255,0.06);border-radius:6px;">TOTAL</td>';
    for (const c of cols) {
        const ct = colTotals[c.k];
        html += '<td style="padding:8px;text-align:center;background:rgba(255,255,255,0.06);border-radius:6px;">';
        html += '<div style="color:#fff;font-size:18px;font-weight:900;line-height:1;">' + fmt(ct.count) + '</div>';
        if (hasFileTx && ct.sumCargas > 0) html += '<div style="color:#25d366;font-size:10px;margin-top:3px;font-family:monospace;">$' + fmt(ct.sumCargas) + '</div>';
        if (ct.sinLinea > 0) html += '<div style="color:#ff8080;font-size:9.5px;margin-top:2px;">⚠ ' + ct.sinLinea + '</div>';
        html += '</td>';
    }
    html += '<td style="padding:8px;text-align:center;background:linear-gradient(135deg,rgba(255,215,0,0.18),rgba(0,212,255,0.10));border:1px solid rgba(255,215,0,0.40);border-radius:6px;">';
    html += '<div style="color:#ffd700;font-size:18px;font-weight:900;line-height:1;">' + fmt(grandTotal.count) + '</div>';
    if (hasFileTx && grandTotal.sumCargas > 0) html += '<div style="color:#25d366;font-size:10px;margin-top:3px;font-family:monospace;">$' + fmt(grandTotal.sumCargas) + '</div>';
    if (grandTotal.sinLinea > 0) html += '<div style="color:#ff8080;font-size:9.5px;margin-top:2px;">⚠ ' + grandTotal.sinLinea + ' sin línea</div>';
    html += '</td>';
    html += '</tr>';
    html += '</tbody></table>';
    html += '</div>'; // overflow-x

    if (hasSinLinea) {
        html += '<div style="margin-top:10px;padding:8px 12px;background:rgba(255,128,128,0.06);border:1px solid rgba(255,128,128,0.30);border-radius:8px;color:#ffb0b0;font-size:11.5px;line-height:1.5;">';
        html += '⚠ <strong>' + fmt(sinLineaTotal) + '</strong> usuario' + (sinLineaTotal === 1 ? '' : 's') + ' del archivo no tiene' + (sinLineaTotal === 1 ? '' : 'n') + ' línea asignada (no aparece' + (sinLineaTotal === 1 ? '' : 'n') + ' en Equipos). De esos, <strong>' + fmt(sinLineaSinApp) + '</strong> tampoco tiene' + (sinLineaSinApp === 1 ? '' : 'n') + ' app — son los más complicados de recontactar. Revisá la hoja "⚠ Sin línea asignada" del XLSX o cargalos en el equipo correspondiente desde 📊 Equipos.';
        html += '</div>';
    }
    html += '</div>'; // panorama card

    return html;
}

function _recontactSetCellFilter(bucket, appStatus) {
    if (!window._recontactFilters) window._recontactFilters = {};
    // Toggle: si ya está activa esa celda, quitar filtro.
    const f = window._recontactFilters;
    if (f.bucket === bucket && f.appStatus === appStatus) {
        f.bucket = 'all';
        f.appStatus = 'all';
    } else {
        f.bucket = bucket;
        f.appStatus = appStatus;
    }
    loadRecontactSection();
}

function _recontactFilterClear() {
    window._recontactFilters = { tier: 'all', bucket: 'all', appStatus: 'all' };
    loadRecontactSection();
}

async function recontactDownloadXlsx() {
    const items = _recontactState.items || [];
    const summary = _recontactState.summary || {};
    if (items.length === 0) { showToast('No hay datos para exportar', 'error'); return; }
    showToast('⏳ Generando XLSX por hojas…', 'info');
    try {
        const r = await authFetch('/api/admin/recontact/export.xlsx', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ items, summary })
        });
        if (!r.ok) {
            let msg = 'Error ' + r.status;
            try { const j = await r.json(); if (j && j.error) msg = j.error; } catch (_) {}
            showToast('❌ ' + msg, 'error');
            return;
        }
        const blob = await r.blob();
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'recontactacion-' + new Date().toISOString().slice(0, 10) + '.xlsx';
        document.body.appendChild(a);
        a.click();
        setTimeout(() => { try { URL.revokeObjectURL(url); a.remove(); } catch (_) {} }, 1500);
        showToast('✅ XLSX descargado', 'success');
    } catch (e) {
        showToast('Error: ' + (e.message || e), 'error');
    }
}

async function recontactDownloadCsv() {
    const items = _recontactState.items || [];
    if (items.length === 0) { showToast('No hay datos para exportar', 'error'); return; }
    try {
        const r = await authFetch('/api/admin/recontact/export.csv', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ items })
        });
        if (!r.ok) {
            showToast('Error descargando CSV (' + r.status + ')', 'error');
            return;
        }
        const blob = await r.blob();
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'recontactacion-' + new Date().toISOString().slice(0, 10) + '.csv';
        document.body.appendChild(a);
        a.click();
        setTimeout(() => { try { URL.revokeObjectURL(url); a.remove(); } catch (_) {} }, 1500);
        showToast('✅ CSV descargado', 'success');
    } catch (e) {
        showToast('Error: ' + (e.message || e), 'error');
    }
}

async function loadStatsAll() {
    await Promise.all([loadStatsRefreshState(), loadCsvImportState(), loadSegmentsAndWeekly()]);
}

// --- CSV import desde JUGAYGANA ---
async function loadCsvImportState() {
    try {
        const r = await authFetch('/api/admin/stats/import-csv');
        if (!r.ok) return;
        const d = await r.json();
        renderCsvImportState(d.state || {}, d.lastImport || null);
    } catch (e) { console.warn('loadCsvImportState', e); }
}

function renderCsvImportState(state, lastImport) {
    const el = document.getElementById('csvImportState');
    if (!el) return;
    if (state.running) {
        el.innerHTML = '⏳ Procesando: <strong style="color:#d6b3ff;">' +
            (state.valid || 0) + ' válidas / ' + (state.skipped || 0) + ' descartadas</strong>';
    } else if (lastImport) {
        const when = new Date(lastImport.uploadedAt).toLocaleString('es-AR');
        const period = lastImport.periodFrom && lastImport.periodTo
            ? new Date(lastImport.periodFrom).toLocaleDateString('es-AR') + ' - ' + new Date(lastImport.periodTo).toLocaleDateString('es-AR')
            : 'periodo no detectado';
        el.innerHTML = '✅ Último import: <strong>' + escapeHtml(when) + '</strong> · ' +
            (lastImport.uniqueUsers || 0) + ' jugadores · ' +
            (lastImport.validRows || 0) + ' transacciones · ' +
            'periodo ' + period;
    } else {
        el.innerHTML = 'Sin imports todavía.';
    }
}

let _csvImportPollInterval = null;

async function handleCsvImportUrl() {
    const input = document.getElementById('csvImportUrl');
    const btn = document.getElementById('csvImportUrlBtn');
    const url = (input && input.value || '').trim();
    if (!url) {
        showToast('Pegá un link de Google Sheets', 'info');
        return;
    }
    if (!/docs\.google\.com\/spreadsheets/.test(url)) {
        showToast('No parece un link de Google Sheets', 'error');
        return;
    }
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Descargando…'; }
    try {
        const r = await authFetch('/api/admin/stats/import-csv-url', {
            method: 'POST',
            body: JSON.stringify({ url })
        });
        const d = await r.json();
        if (d.success === false && d.message) {
            showToast(d.message, 'info');
        } else if (d.skipped) {
            showToast(d.message || 'Sheet ya importado previamente', 'info');
        } else if (d.error) {
            showToast(d.error, 'error');
        } else {
            showToast('Sheet descargado, procesando…', 'success');
            startCsvImportPolling();
            if (input) input.value = '';
        }
    } catch (e) {
        console.error(e);
        showToast('Error iniciando import', 'error');
    } finally {
        if (btn) { btn.disabled = false; btn.textContent = '🔗 Importar desde link'; }
    }
}

function startCsvImportPolling() {
    if (_csvImportPollInterval) clearInterval(_csvImportPollInterval);
    _csvImportPollInterval = setInterval(async () => {
        await loadCsvImportState();
        const stEl = document.getElementById('csvImportState');
        if (stEl && stEl.innerHTML.startsWith('✅')) {
            clearInterval(_csvImportPollInterval);
            _csvImportPollInterval = null;
            await loadSegmentsAndWeekly();
            if (document.getElementById('statsTabPlayers').style.display !== 'none') loadPlayersList();
            if (document.getElementById('statsTabRoi').style.display !== 'none') loadRoiBucket();
            showToast('✅ Import completo, panel actualizado', 'success');
        }
    }, 2000);
}

async function handleCsvImport(ev) {
    const file = ev.target.files && ev.target.files[0];
    if (!file) return;
    if (file.size > 100 * 1024 * 1024) {
        showToast('El archivo supera 100MB. Pediendo a alguien que lo recorte.', 'error');
        return;
    }
    const btn = document.getElementById('csvImportBtn');
    if (btn) { btn.style.opacity = '0.5'; btn.style.pointerEvents = 'none'; btn.textContent = '⏳ Leyendo archivo…'; }

    try {
        // Leer como texto (no binario) — soporta .csv y .txt.
        const text = await file.text();
        if (btn) btn.textContent = '⏳ Subiendo (' + Math.round(text.length / 1024) + ' KB)…';

        const r = await fetch(API_URL + '/api/admin/stats/import-csv', {
            method: 'POST',
            headers: {
                'Authorization': 'Bearer ' + currentToken,
                'Content-Type': 'text/csv'
            },
            body: text
        });
        const d = await r.json();

        if (d.success === false && d.message) {
            showToast(d.message, 'info');
        } else if (d.skipped) {
            showToast(d.message || 'Archivo ya importado previamente', 'info');
        } else {
            showToast('Import iniciado en background', 'success');
            startCsvImportPolling();
        }
    } catch (e) {
        console.error(e);
        showToast('Error procesando el archivo', 'error');
    } finally {
        if (btn) {
            btn.style.opacity = '1';
            btn.style.pointerEvents = 'auto';
            btn.textContent = '📤 Subir CSV de JUGAYGANA';
        }
        // Reset el input para que se pueda volver a subir el mismo archivo.
        ev.target.value = '';
    }
}

async function loadStatsRefreshState() {
    try {
        const r = await authFetch('/api/admin/stats/refresh', { method: 'GET' });
        if (!r.ok) return;
        const d = await r.json();
        renderRefreshState(d.state || {});
    } catch (e) { console.warn('loadStatsRefreshState', e); }
}

function renderRefreshState(s) {
    const el = document.getElementById('statsRefreshState');
    if (!el) return;
    if (s.running) {
        const pct = s.total > 0 ? Math.round((s.done / s.total) * 100) : 0;
        el.innerHTML = '⏳ Refrescando JUGAYGANA: <strong style="color:#ffd700;">' + s.done + ' / ' + s.total + '</strong> (' + pct + '%)' +
            (s.errors ? ' — <span style="color:#ff8080;">' + s.errors + ' errores</span>' : '');
    } else if (s.finishedAt) {
        const when = new Date(s.finishedAt).toLocaleString('es-AR');
        el.innerHTML = '✅ Último refresh: <strong>' + escapeHtml(when) + '</strong> — ' + (s.done || 0) + ' jugadores procesados' +
            (s.errors ? ' (' + s.errors + ' errores)' : '');
    } else {
        el.innerHTML = 'Esperando primer refresh…';
    }
}

let _refreshPollInterval = null;
async function triggerStatsRefresh() {
    const btn = document.getElementById('statsRefreshBtn');
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Iniciando…'; }
    try {
        const r = await authFetch('/api/admin/stats/refresh', { method: 'POST' });
        const d = await r.json();
        if (d.success === false && d.message) {
            showToast(d.message, 'info');
        } else {
            showToast('Refresh iniciado en background', 'success');
        }
        renderRefreshState(d.state || {});
        // Polear cada 3s mientras corre.
        if (_refreshPollInterval) clearInterval(_refreshPollInterval);
        _refreshPollInterval = setInterval(async () => {
            await loadStatsRefreshState();
            const stEl = document.getElementById('statsRefreshState');
            if (stEl && stEl.innerHTML.startsWith('✅')) {
                clearInterval(_refreshPollInterval);
                _refreshPollInterval = null;
                // Recargar las tablas con datos frescos.
                await loadSegmentsAndWeekly();
                if (document.getElementById('statsTabPlayers').style.display !== 'none') loadPlayersList();
                if (document.getElementById('statsTabRoi').style.display !== 'none') loadRoiBucket();
            }
        }, 3000);
    } catch (e) {
        showToast('Error iniciando refresh', 'error');
        console.error(e);
    } finally {
        if (btn) { btn.disabled = false; btn.textContent = '🔁 Refrescar JUGAYGANA'; }
    }
}

async function loadSegmentsAndWeekly() {
    try {
        const r = await authFetch('/api/admin/stats/segments');
        if (!r.ok) return;
        const d = await r.json();
        renderTopMetrics(d);
        renderUrgentFocus(d.urgentSegments || []);
        renderWeeklyHeader(d.weekly || {});
        renderRecoveryHeader(d.recovery || {});
        renderSegmentsMatrix(d.matrix || {}, d.tierTotals || {}, d.activityTotals || {}, d.appBreakdownByCell || {});
        renderTierDeepDive(d);
    } catch (e) { console.warn('loadSegmentsAndWeekly', e); }
}

// ============================================
// NUEVAS MÉTRICAS GLOBALES — chips arriba del panel
// ============================================
function renderTopMetrics(d) {
    const el = document.getElementById('statsTopMetrics');
    if (!el) return;
    const w = d.weekly || {};
    const rec = d.recoverable || {};
    const recv = d.recovery || {};
    const an = d.appNotifs || null;

    const fmtMoney = (n) => '$' + Number(n || 0).toLocaleString('es-AR');

    const arrow = (w.delta || 0) > 0 ? '📈' : ((w.delta || 0) < 0 ? '📉' : '➡️');
    const arrowColor = (w.delta || 0) > 0 ? '#25d366' : ((w.delta || 0) < 0 ? '#ff5050' : '#aaa');

    let html = '';
    html += _bigChip('💰 Activos esta semana', String(w.activeThisWeek || 0),
        '<span style="color:' + arrowColor + ';font-size:11px;font-weight:700;">' + arrow + ' ' + (w.delta > 0 ? '+' : '') + (w.delta || 0) + ' (' + (w.deltaPct >= 0 ? '+' : '') + (w.deltaPct || 0) + '%)</span>',
        '#ffd700');
    html += _bigChip('🎯 Recuperables totales', String(rec.total || 0),
        'En riesgo + perdidos + inactivos<br>(sin oportunistas)',
        '#ff7f50');
    html += _bigChip('💎 Potencial de recuperación', fmtMoney(rec.potentialRevenue),
        'Estimación según ticket avg × conv. esperada',
        '#25d366');
    html += _bigChip('📲 ROI pushes (30d)', (recv.roiX || 0) + '×',
        'Bonos: ' + fmtMoney(recv.totalBonus) + ' → cargas: ' + fmtMoney(recv.totalRealDeposit),
        '#9b30ff');

    // Chip de salud del canal de push: cuántos tienen app + notifs hoy,
    // cómo cambió vs ayer / vs hace 7 días, y sparkline de los últimos 30 días.
    if (an) {
        html += _appNotifChip(an);
    }

    el.innerHTML = html;
}

// Chip especial con sparkline del canal app+notifs.
function _appNotifChip(an) {
    const today = Number(an.today || 0);
    const dY = an.deltaYesterday;
    const d7 = an.delta7d;
    const cov = Number(an.coveragePct || 0);

    const fmtDelta = (v) => {
        if (v == null) return '<span style="color:#888;">— sin datos</span>';
        const n = Number(v);
        const sign = n > 0 ? '+' : '';
        const color = n > 0 ? '#25d366' : (n < 0 ? '#ff5050' : '#aaa');
        const arrow = n > 0 ? '↑' : (n < 0 ? '↓' : '·');
        return '<span style="color:' + color + ';font-weight:700;">' + arrow + ' ' + sign + n + '</span>';
    };

    const series = Array.isArray(an.series) ? an.series : [];
    const sparkline = _renderSparkline(series.map(s => Number(s.withBoth || 0)));

    const sub =
        '<div style="display:flex;gap:8px;margin-bottom:6px;">' +
            '<span style="font-size:10px;color:#888;">Ayer:</span> ' + fmtDelta(dY) +
            '<span style="font-size:10px;color:#888;margin-left:6px;">7d:</span> ' + fmtDelta(d7) +
        '</div>' +
        '<div style="color:#aaa;font-size:10px;margin-bottom:4px;">' +
            cov + '% del total · ' + (an.totalUsersToday || 0) + ' usuarios' +
        '</div>' +
        sparkline;

    return _bigChip('📲 Con app + notifs', String(today), sub, '#00d4ff');
}

// Sparkline simple en SVG: 30 puntos, polyline, sin labels.
// Sin librerías — un SVG inline pequeño.
function _renderSparkline(values) {
    if (!Array.isArray(values) || values.length < 2) {
        return '<div style="color:#666;font-size:10px;">Acumulando datos…</div>';
    }
    const w = 200, h = 36;
    const max = Math.max(...values, 1);
    const min = Math.min(...values, 0);
    const range = max - min || 1;
    const stepX = w / (values.length - 1);
    const points = values.map((v, i) => {
        const x = i * stepX;
        const y = h - ((v - min) / range) * (h - 4) - 2;
        return x.toFixed(1) + ',' + y.toFixed(1);
    }).join(' ');
    const last = values[values.length - 1];
    const lastX = (values.length - 1) * stepX;
    const lastY = h - ((last - min) / range) * (h - 4) - 2;
    return '<svg viewBox="0 0 ' + w + ' ' + h + '" preserveAspectRatio="none" style="width:100%;height:36px;display:block;">' +
        '<polyline points="' + points + '" fill="none" stroke="#00d4ff" stroke-width="1.5" stroke-linejoin="round"/>' +
        '<circle cx="' + lastX.toFixed(1) + '" cy="' + lastY.toFixed(1) + '" r="2.5" fill="#00d4ff"/>' +
    '</svg>';
}

function _bigChip(label, value, sub, color) {
    return '<div style="flex:1;min-width:200px;background:rgba(0,0,0,0.40);border:1px solid rgba(255,255,255,0.08);border-radius:12px;padding:14px 16px;">' +
        '<div style="color:#888;font-size:10px;text-transform:uppercase;letter-spacing:1.5px;margin-bottom:6px;">' + escapeHtml(label) + '</div>' +
        '<div style="color:' + color + ';font-size:24px;font-weight:800;line-height:1;margin-bottom:6px;">' + escapeHtml(value) + '</div>' +
        '<div style="color:#aaa;font-size:11px;line-height:1.4;">' + sub + '</div>' +
        '</div>';
}

// ============================================
// FOCO URGENTE — top 5 segmentos por urgencia
// ============================================
function renderUrgentFocus(segments) {
    const el = document.getElementById('statsUrgentFocus');
    if (!el) return;
    if (!segments || segments.length === 0) {
        el.innerHTML = '<div style="background:rgba(0,255,136,0.06);border:1px solid rgba(0,255,136,0.25);border-radius:10px;padding:12px;color:#25d366;font-size:13px;font-weight:600;">✅ No hay segmentos urgentes. Todo bajo control.</div>';
        return;
    }

    const tierLabel = {VIP:'🏆 VIP', ORO:'🥇 ORO', PLATA:'🥈 PLATA', BRONCE:'🥉 BRONCE', NUEVO:'🆕 NUEVO', SIN_DATOS:'⚪ Sin datos'};
    const stateLabel = {ACTIVO:'Activo', EN_RIESGO:'En riesgo', PERDIDO:'Perdido', INACTIVO:'Inactivo', NUEVO:'Nuevo'};

    let html = '<div style="background:linear-gradient(135deg, rgba(255,80,80,0.08), rgba(212,175,55,0.06));border:1px solid rgba(255,80,80,0.30);border-radius:12px;padding:14px;">';
    html += '<div style="color:#ff7f50;font-size:11px;text-transform:uppercase;letter-spacing:1.5px;font-weight:700;margin-bottom:10px;">🔴 Foco urgente — atacá esto primero</div>';
    html += '<div style="display:flex;flex-direction:column;gap:8px;">';

    for (const seg of segments) {
        const playbook = _findPlaybook(seg.tier, seg.state);
        const segLabel = tierLabel[seg.tier] + ' · ' + stateLabel[seg.state];
        const $ = '$' + Number(seg.potentialRevenue || 0).toLocaleString('es-AR');
        const strategy = playbook ? playbook.strategy : 'Recuperación estándar';
        const bonusHint = playbook ? playbook.bonus : '—';
        const withApp = Number(seg.withApp || 0);
        const noApp = Number(seg.noApp || 0);

        html += '<div style="display:flex;align-items:center;gap:12px;background:rgba(0,0,0,0.35);padding:10px 12px;border-radius:8px;border-left:3px solid #ff7f50;flex-wrap:wrap;">';
        html += '<div style="flex:0 0 auto;background:rgba(255,127,80,0.12);color:#ff7f50;font-size:18px;font-weight:800;padding:8px 12px;border-radius:8px;min-width:64px;text-align:center;">' + (seg.count || 0) + '</div>';
        html += '<div style="flex:1;min-width:200px;">';
        html += '<div style="color:#fff;font-size:13px;font-weight:700;margin-bottom:2px;">' + escapeHtml(segLabel) + '</div>';
        html += '<div style="color:#aaa;font-size:11px;line-height:1.4;">🎯 <strong style="color:#ffd700;">' + escapeHtml(strategy) + '</strong> · ' + escapeHtml(bonusHint) + ' · ~' + $ + ' potencial</div>';
        // Breakdown: con app (push) vs sin app (whatsapp). Útil para saber
        // dónde mandar push directo y dónde hace falta recontactar humano.
        html += '<div style="margin-top:6px;display:flex;gap:8px;flex-wrap:wrap;font-size:11px;">';
        html += '<span style="background:rgba(37,211,102,0.10);color:#25d366;padding:3px 8px;border-radius:5px;font-weight:700;">📱 ' + withApp + ' con app</span>';
        html += '<span style="background:rgba(255,170,0,0.10);color:#ffaa00;padding:3px 8px;border-radius:5px;font-weight:700;">💬 ' + noApp + ' sin app (WhatsApp)</span>';
        html += '</div>';
        html += '</div>';
        html += '<div style="display:flex;gap:6px;flex-wrap:wrap;">';
        if (withApp > 0) {
            html += '<button onclick="openRecoveryModal(\'' + seg.tier + '\',\'' + seg.state + '\')" style="padding:8px 12px;background:linear-gradient(135deg,#ff7f50,#ff5050);color:#fff;border:none;border-radius:7px;cursor:pointer;font-weight:700;font-size:12px;white-space:nowrap;">📲 Push (' + withApp + ')</button>';
        }
        if (noApp > 0) {
            html += '<button onclick="openRecoveryWhatsApp(\'' + seg.tier + '\',\'' + seg.state + '\')" style="padding:8px 12px;background:linear-gradient(135deg,#25d366,#128c4f);color:#fff;border:none;border-radius:7px;cursor:pointer;font-weight:700;font-size:12px;white-space:nowrap;" title="Descargar CSV con teléfonos para campaña por WhatsApp">💬 WhatsApp (' + noApp + ')</button>';
        }
        html += '</div>';
        html += '</div>';
    }
    html += '</div></div>';

    el.innerHTML = html;
}

function _findPlaybook(tier, state) {
    return PLAYBOOK_DATA.find(p => p.seg.includes(tier) && p.seg.includes(state))
        || PLAYBOOK_DATA.find(p => p.seg.includes(tier));
}

// ============================================
// BLOQUES POR TIER — debajo de la matriz
// ============================================
function renderTierDeepDive(d) {
    const el = document.getElementById('statsTierDeepDive');
    if (!el) return;
    const matrix = d.matrix || {};
    const tierTotals = d.tierTotals || {};
    const recoverableByTier = (d.recoverable && d.recoverable.byTier) || {};
    const avgTicketByTier = d.avgTicketByTier || {};

    const tiers = ['VIP', 'ORO', 'PLATA', 'BRONCE', 'NUEVO', 'SIN_DATOS'];
    const states = ['ACTIVO', 'EN_RIESGO', 'PERDIDO', 'INACTIVO', 'NUEVO'];
    const tierLabel = {VIP:'🏆 VIP', ORO:'🥇 ORO', PLATA:'🥈 PLATA', BRONCE:'🥉 BRONCE', NUEVO:'🆕 NUEVO', SIN_DATOS:'⚪ Sin datos'};
    const stateLabel = {ACTIVO:'✅ Activo', EN_RIESGO:'⚠️ En riesgo', PERDIDO:'💔 Perdido', INACTIVO:'☠️ Inactivo', NUEVO:'🆕 Nuevo'};
    const stateColor = {ACTIVO:'#25d366', EN_RIESGO:'#ffaa00', PERDIDO:'#ff5050', INACTIVO:'#888', NUEVO:'#1a73e8'};
    const tierColor = {VIP:'#ffd700', ORO:'#f7931e', PLATA:'#c0c0c0', BRONCE:'#cd7f32', NUEVO:'#1a73e8', SIN_DATOS:'#666'};
    const tierAccent = {VIP:'rgba(255,215,0,0.25)', ORO:'rgba(247,147,30,0.25)', PLATA:'rgba(192,192,192,0.20)', BRONCE:'rgba(205,127,50,0.20)', NUEVO:'rgba(26,115,232,0.20)', SIN_DATOS:'rgba(102,102,102,0.20)'};

    let html = '';
    for (const t of tiers) {
        const total = tierTotals[t] || 0;
        if (total === 0 && t !== 'VIP') continue; // ocultamos tiers vacíos salvo VIP siempre visible
        const recov = recoverableByTier[t] || { count: 0, potentialRevenue: 0 };
        const ticket = avgTicketByTier[t] || 0;

        html += '<div style="background:rgba(0,0,0,0.35);border:1px solid ' + tierAccent[t] + ';border-radius:12px;padding:14px;">';

        // Header del tier
        html += '<div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:12px;padding-bottom:10px;border-bottom:1px dashed rgba(255,255,255,0.10);">';
        html += '<div style="color:' + tierColor[t] + ';font-size:18px;font-weight:800;">' + tierLabel[t] + '</div>';
        html += '<div style="color:#888;font-size:11px;">' + total + ' jugadores</div>';
        if (ticket > 0) html += '<div style="color:#888;font-size:11px;">·  Ticket avg: <strong style="color:#ffd700;">$' + Number(ticket).toLocaleString('es-AR') + '</strong></div>';
        if (recov.count > 0) html += '<div style="margin-left:auto;background:rgba(255,127,80,0.10);color:#ff7f50;padding:4px 10px;border-radius:6px;font-size:11px;font-weight:700;">🎯 ' + recov.count + ' recuperables · ~$' + Number(recov.potentialRevenue).toLocaleString('es-AR') + '</div>';
        html += '</div>';

        // Chips por estado
        html += '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px;">';
        for (const s of states) {
            const c = matrix[t + '-' + s] || 0;
            if (c === 0) continue;
            html += '<div style="background:rgba(0,0,0,0.40);border:1px solid rgba(255,255,255,0.08);border-radius:6px;padding:6px 10px;font-size:11px;">';
            html += '<span style="color:' + stateColor[s] + ';font-weight:700;">' + stateLabel[s] + '</span>: ';
            html += '<strong style="color:#fff;">' + c + '</strong>';
            html += '</div>';
        }
        html += '</div>';

        // Estrategia recomendada (última fila destacada — embedded del playbook)
        const recoverableStates = ['EN_RIESGO', 'PERDIDO', 'INACTIVO'];
        const hasRecoverable = recoverableStates.some(s => (matrix[t + '-' + s] || 0) > 0);
        if (hasRecoverable) {
            html += '<div style="background:rgba(212,175,55,0.05);border:1px solid rgba(212,175,55,0.25);border-radius:8px;padding:10px 12px;">';
            html += '<div style="color:#ffd700;font-size:11px;text-transform:uppercase;letter-spacing:1px;font-weight:700;margin-bottom:8px;">🎯 Recontactación recomendada</div>';
            html += '<div style="display:flex;flex-direction:column;gap:6px;">';
            for (const s of recoverableStates) {
                const c = matrix[t + '-' + s] || 0;
                if (c === 0) continue;
                const pb = _findPlaybook(t, s);
                if (!pb) continue;
                html += '<div style="display:flex;align-items:center;gap:10px;padding:6px 0;border-bottom:1px dashed rgba(255,255,255,0.06);flex-wrap:wrap;">';
                html += '<span style="color:' + stateColor[s] + ';font-weight:700;font-size:11px;min-width:90px;">' + stateLabel[s] + ' (' + c + ')</span>';
                html += '<span style="color:#fff;font-size:12px;flex:1;min-width:200px;"><strong>' + escapeHtml(pb.strategy) + '</strong> · ' + escapeHtml(pb.bonus) + '</span>';
                html += '<span style="color:#888;font-size:10px;font-style:italic;">' + escapeHtml(pb.why) + '</span>';
                html += '<button onclick="openRecoveryModal(\'' + t + '\',\'' + s + '\')" style="padding:5px 10px;background:linear-gradient(135deg,#9b30ff,#6a0dad);color:#fff;border:none;border-radius:5px;cursor:pointer;font-size:11px;font-weight:700;white-space:nowrap;">📲 Push (' + c + ')</button>';
                html += '</div>';
            }
            html += '</div></div>';
        } else if (total > 0) {
            // Sólo activos — sugerencia de retención
            const pb = _findPlaybook(t, 'ACTIVO');
            if (pb) {
                html += '<div style="background:rgba(37,211,102,0.05);border:1px solid rgba(37,211,102,0.20);border-radius:8px;padding:10px 12px;">';
                html += '<div style="color:#25d366;font-size:11px;text-transform:uppercase;letter-spacing:1px;font-weight:700;margin-bottom:6px;">✅ Mantenimiento (todos activos)</div>';
                html += '<div style="color:#fff;font-size:12px;line-height:1.5;"><strong>' + escapeHtml(pb.strategy) + '</strong> · ' + escapeHtml(pb.bonus);
                html += '<br><span style="color:#aaa;font-size:11px;">' + escapeHtml(pb.why) + '</span></div>';
                html += '</div>';
            }
        }

        html += '</div>';
    }

    el.innerHTML = html;
}

function renderWeeklyHeader(w) {
    const el = document.getElementById('statsWeeklyHeader');
    if (!el) return;
    const arrow = w.delta > 0 ? '📈' : (w.delta < 0 ? '📉' : '➡️');
    const color = w.delta > 0 ? '#25d366' : (w.delta < 0 ? '#ff5050' : '#aaa');
    el.innerHTML = '<div style="background:rgba(0,0,0,0.30);border:1px solid rgba(255,255,255,0.08);border-radius:10px;padding:12px;">' +
        '<div style="color:#aaa;font-size:11px;text-transform:uppercase;letter-spacing:1px;margin-bottom:6px;">Comparativo semanal</div>' +
        '<div style="font-size:14px;color:#fff;">Jugadores activos esta semana: <strong style="color:#ffd700;font-size:18px;">' + (w.activeThisWeek || 0) + '</strong>' +
        '   |   Semana pasada: ' + (w.activeLastWeek || 0) +
        '   |   Δ: <strong style="color:' + color + ';">' + arrow + ' ' + (w.delta > 0 ? '+' : '') + (w.delta || 0) + ' (' + (w.deltaPct >= 0 ? '+' : '') + (w.deltaPct || 0) + '%)</strong></div>' +
        '</div>';
}

function renderRecoveryHeader(r) {
    const el = document.getElementById('statsRecoveryHeader');
    if (!el) return;
    if (!r.sent) {
        el.innerHTML = '<div style="background:rgba(0,0,0,0.30);border:1px dashed rgba(255,255,255,0.10);border-radius:10px;padding:12px;color:#888;font-size:12px;">📲 Sin pushes de recuperación enviados todavía. Mandá uno desde la matriz de abajo.</div>';
        return;
    }
    const recovered = r.recovered || 0;
    const recPct = r.sent > 0 ? Math.round((recovered / r.sent) * 100) : 0;
    el.innerHTML = '<div style="background:rgba(37,211,102,0.06);border:1px solid rgba(37,211,102,0.25);border-radius:10px;padding:12px;">' +
        '<div style="color:#25d366;font-size:11px;text-transform:uppercase;letter-spacing:1px;margin-bottom:6px;">Efectividad de recuperación (últ. 30d)</div>' +
        '<div style="font-size:13px;color:#fff;line-height:1.6;">' +
        'Pushes enviados: <strong>' + r.sent + '</strong>   |   ' +
        'Recuperaron real: <strong style="color:#25d366;">' + recovered + ' (' + recPct + '%)</strong>   |   ' +
        'Solo bono (oportunistas): <strong style="color:#ffaa00;">' + (r.opportunist || 0) + '</strong>   |   ' +
        'Sin respuesta: <strong style="color:#888;">' + (r.no_response || 0) + '</strong>   |   ' +
        'Pendientes: <strong>' + (r.pending || 0) + '</strong><br>' +
        'Bonos dados: <strong>$' + Number(r.totalBonus || 0).toLocaleString('es-AR') + '</strong>   →   ' +
        'Cargas reales generadas: <strong style="color:#25d366;">$' + Number(r.totalRealDeposit || 0).toLocaleString('es-AR') + '</strong>   =   ' +
        '<strong style="color:#ffd700;">ROI ' + (r.roiX || 0) + '×</strong>' +
        '</div></div>';
}

function renderSegmentsMatrix(matrix, tierTotals, activityTotals, appBreakdown) {
    const el = document.getElementById('statsSegmentsMatrix');
    if (!el) return;
    const breakdown = appBreakdown || {};
    const tiers = ['VIP', 'ORO', 'PLATA', 'BRONCE', 'NUEVO', 'SIN_DATOS'];
    const states = ['ACTIVO', 'EN_RIESGO', 'PERDIDO', 'INACTIVO', 'NUEVO'];
    const tierLabel = {VIP:'🏆 VIP', ORO:'🥇 ORO', PLATA:'🥈 PLATA', BRONCE:'🥉 BRONCE', NUEVO:'🆕 NUEVO', SIN_DATOS:'⚪ Sin datos'};
    const stateLabel = {ACTIVO:'✅ Activo', EN_RIESGO:'⚠️ En riesgo', PERDIDO:'💔 Perdido', INACTIVO:'☠️ Inactivo', NUEVO:'🆕 Nuevo'};
    const cellColor = {
        ACTIVO: 'rgba(37,211,102,0.10)',
        EN_RIESGO: 'rgba(255,170,0,0.15)',
        PERDIDO: 'rgba(255,80,80,0.18)',
        INACTIVO: 'rgba(120,120,120,0.10)',
        NUEVO: 'rgba(26,115,232,0.12)'
    };

    let html = '<table style="width:100%;border-collapse:collapse;font-size:12px;">';
    html += '<thead><tr><th style="text-align:left;padding:8px;color:#aaa;border-bottom:1px solid rgba(255,255,255,0.10);">Tier \\ Estado</th>';
    for (const s of states) {
        html += '<th style="padding:8px;color:#aaa;border-bottom:1px solid rgba(255,255,255,0.10);text-align:center;">' + stateLabel[s] + '<br><small style="color:#666;font-weight:400;">' + (activityTotals[s] || 0) + ' total</small></th>';
    }
    html += '<th style="padding:8px;color:#aaa;border-bottom:1px solid rgba(255,255,255,0.10);text-align:center;">Σ tier</th></tr></thead><tbody>';

    for (const t of tiers) {
        html += '<tr>';
        html += '<td style="padding:8px;color:#fff;font-weight:700;border-bottom:1px solid rgba(255,255,255,0.05);">' + tierLabel[t] + '</td>';
        for (const s of states) {
            const c = matrix[t + '-' + s] || 0;
            const br = breakdown[t + '-' + s] || { withApp: 0, noApp: 0 };
            const isUrgent = (t === 'VIP' || t === 'ORO') && (s === 'EN_RIESGO' || s === 'PERDIDO');
            const showBtn = c > 0 && (s === 'EN_RIESGO' || s === 'PERDIDO' || s === 'INACTIVO');
            html += '<td style="padding:8px;text-align:center;background:' + cellColor[s] + ';border-bottom:1px solid rgba(255,255,255,0.05);' + (isUrgent ? 'border:2px solid #ff5050;' : '') + '">';
            html += '<div style="font-size:18px;font-weight:800;color:#fff;">' + c + '</div>';
            // Breakdown app/no-app debajo del total
            if (c > 0 && (br.withApp > 0 || br.noApp > 0)) {
                html += '<div style="font-size:9.5px;color:#aaa;margin-top:2px;line-height:1.3;">';
                html += '<span style="color:#25d366;">📱 ' + br.withApp + '</span>';
                html += ' · ';
                html += '<span style="color:#ffaa00;">💬 ' + br.noApp + '</span>';
                html += '</div>';
            }
            if (showBtn) {
                html += '<div style="display:flex;gap:3px;justify-content:center;flex-wrap:wrap;margin-top:4px;">';
                if (br.withApp > 0) {
                    html += '<button onclick="openRecoveryModal(\'' + t + '\',\'' + s + '\')" title="Mandar push a los que tienen app" style="font-size:9.5px;padding:3px 6px;background:rgba(255,255,255,0.10);border:1px solid rgba(255,255,255,0.20);color:#fff;border-radius:4px;cursor:pointer;font-weight:600;">📲</button>';
                }
                if (br.noApp > 0) {
                    html += '<button onclick="openRecoveryWhatsApp(\'' + t + '\',\'' + s + '\')" title="Descargar CSV con teléfonos para WhatsApp" style="font-size:9.5px;padding:3px 6px;background:rgba(37,211,102,0.15);border:1px solid rgba(37,211,102,0.40);color:#25d366;border-radius:4px;cursor:pointer;font-weight:600;">💬</button>';
                }
                html += '</div>';
            }
            html += '</td>';
        }
        html += '<td style="padding:8px;text-align:center;color:#ffd700;font-weight:700;border-bottom:1px solid rgba(255,255,255,0.05);">' + (tierTotals[t] || 0) + '</td>';
        html += '</tr>';
    }
    html += '</tbody></table>';
    html += '<div style="margin-top:10px;color:#888;font-size:11px;">Las celdas con borde rojo (VIP/ORO en riesgo o perdidos) son las más urgentes. <strong style="color:#25d366;">📱</strong> = con app+notifs (push directo) · <strong style="color:#ffaa00;">💬</strong> = sin app (descargar CSV para WhatsApp).</div>';
    el.innerHTML = html;
}

async function loadPlayersList() {
    const c = document.getElementById('statsPlayersContent');
    if (!c) return;
    c.innerHTML = '<div class="empty-state">⏳ Cargando…</div>';
    const params = new URLSearchParams();
    const tier = document.getElementById('playersFilterTier').value;
    const status = document.getElementById('playersFilterStatus').value;
    const opp = document.getElementById('playersFilterOpp').value;
    const sortBy = document.getElementById('playersSortBy').value;
    if (tier) params.set('tier', tier);
    if (status) params.set('activityStatus', status);
    if (opp) params.set('opportunist', opp);
    if (sortBy) params.set('sortBy', sortBy);
    params.set('limit', '200');
    try {
        const r = await authFetch('/api/admin/stats/players?' + params.toString());
        if (!r.ok) { c.innerHTML = '<div class="empty-state">Error cargando.</div>'; return; }
        const d = await r.json();
        renderPlayersList(c, d.players || []);
    } catch (e) {
        c.innerHTML = '<div class="empty-state">Error de conexión.</div>';
    }
}

function renderPlayersList(container, players) {
    if (players.length === 0) {
        container.innerHTML = '<div class="empty-state">No hay jugadores con esos filtros. Tal vez todavía no se ejecutó el refresh.</div>';
        return;
    }
    const tierBadge = {VIP:'🏆', ORO:'🥇', PLATA:'🥈', BRONCE:'🥉', NUEVO:'🆕', SIN_DATOS:'⚪'};
    const stateBadge = {ACTIVO:'✅', EN_RIESGO:'⚠️', PERDIDO:'💔', INACTIVO:'☠️', NUEVO:'🆕'};
    let html = '<table class="report-table"><thead><tr>';
    html += '<th>Tier</th><th>Estado</th><th>Usuario</th><th>Cargas $</th><th>#</th><th>Retiros $</th><th>Bonos dados</th><th>Neto a la casa</th><th>🎁 Reclamos</th><th>Última carga</th><th>Última app</th><th></th>';
    html += '</tr></thead><tbody>';
    for (const p of players) {
        const last = p.lastRealDepositDate ? new Date(p.lastRealDepositDate).toLocaleDateString('es-AR') : '—';
        const lastApp = p.lastSeenApp ? new Date(p.lastSeenApp).toLocaleDateString('es-AR') : '—';
        const oppFlag = p.isOpportunist ? ' <span style="color:#ff5050;font-weight:800;" title="Oportunista — toma bonos sin cargar real">🚩</span>' : '';
        const netColor = (p.netToHouse30d || 0) >= 0 ? '#25d366' : '#ff5050';
        // Celda de reclamos: si tiene, muestra count + $ con click → modal de detalle.
        // Si no tiene, muestra "—".
        let claimsCell = '<small style="color:#666;">—</small>';
        if ((p.giveawayClaimsCount || 0) > 0) {
            const total = Number(p.giveawayTotalClaimed || 0).toLocaleString('es-AR');
            claimsCell = '<button onclick="showUserGiveawayDetail(\'' + escapeHtml(p.username) + '\')" style="padding:4px 8px;background:rgba(155,48,255,0.15);border:1px solid rgba(155,48,255,0.40);color:#c89bff;border-radius:5px;cursor:pointer;font-size:11px;font-weight:700;" title="Ver detalle de reclamos">🎁 ' + p.giveawayClaimsCount + ' · $' + total + '</button>';
        }
        html += '<tr>';
        html += '<td>' + (tierBadge[p.tier] || '') + ' <small>' + escapeHtml(p.tier || '') + '</small></td>';
        html += '<td>' + (stateBadge[p.activityStatus] || '') + '</td>';
        html += '<td><strong style="color:#fff;">' + escapeHtml(p.username || '') + '</strong>' + oppFlag + '</td>';
        html += '<td>$' + Number(p.realDeposits30d || 0).toLocaleString('es-AR') + '</td>';
        html += '<td>' + (p.realChargesCount30d || 0) + '</td>';
        html += '<td>$' + Number(p.withdraws30d || 0).toLocaleString('es-AR') + '</td>';
        html += '<td>$' + Number(p.bonusGiven30d || 0).toLocaleString('es-AR') + '</td>';
        html += '<td><strong style="color:' + netColor + ';">$' + Number(p.netToHouse30d || 0).toLocaleString('es-AR') + '</strong></td>';
        html += '<td>' + claimsCell + '</td>';
        html += '<td><small>' + last + '</small></td>';
        html += '<td><small>' + lastApp + '</small></td>';
        html += '<td><button onclick="suggestStrategyFor(\'' + escapeHtml(p.username) + '\',\'' + p.tier + '\',\'' + p.activityStatus + '\')" style="padding:4px 8px;background:rgba(212,175,55,0.20);border:1px solid rgba(212,175,55,0.45);color:#ffd700;border-radius:4px;cursor:pointer;font-size:10px;font-weight:700;" title="Ver estrategia recomendada">🎯</button></td>';
        html += '</tr>';
    }
    html += '</tbody></table>';
    html += '<div style="color:#888;font-size:11px;margin-top:8px;">Mostrando ' + players.length + ' jugadores. Las columnas son del cache — tocá "Refrescar JUGAYGANA" si están desactualizados.</div>';
    container.innerHTML = html;
}

async function loadRoiBucket() {
    const c = document.getElementById('statsRoiContent');
    if (!c) return;
    c.innerHTML = '<div class="empty-state">⏳ Cargando…</div>';
    try {
        const r = await authFetch('/api/admin/stats/roi-bonus');
        if (!r.ok) { c.innerHTML = '<div class="empty-state">Error cargando.</div>'; return; }
        const d = await r.json();
        renderRoiBuckets(c, d.buckets || []);
    } catch (e) {
        c.innerHTML = '<div class="empty-state">Error de conexión.</div>';
    }
}

function renderRoiBuckets(container, buckets) {
    if (buckets.length === 0) {
        container.innerHTML = '<div class="empty-state">Todavía no hay claims de giveaways en los últimos 30 días.</div>';
        return;
    }
    let html = '<table class="report-table"><thead><tr>';
    html += '<th>Monto del bono</th><th>Veces reclamado</th><th>Total regalado</th><th>Usuarios únicos</th><th>De ellos cargaron real</th><th>Cargas reales generadas</th><th>ROI</th>';
    html += '</tr></thead><tbody>';
    for (const b of buckets) {
        const conv = b.uniqueUsers > 0 ? Math.round((b.usersThatDeposited / b.uniqueUsers) * 100) : 0;
        const roiColor = b.roiX >= 3 ? '#25d366' : (b.roiX >= 1 ? '#ffd700' : '#ff5050');
        html += '<tr>';
        html += '<td><strong style="color:#fff;">$' + Number(b.amount).toLocaleString('es-AR') + '</strong></td>';
        html += '<td>' + b.count + '</td>';
        html += '<td>$' + Number(b.totalGiven).toLocaleString('es-AR') + '</td>';
        html += '<td>' + b.uniqueUsers + '</td>';
        html += '<td>' + b.usersThatDeposited + ' <small style="color:#888;">(' + conv + '%)</small></td>';
        html += '<td>$' + Number(b.realDepositsFromThem).toLocaleString('es-AR') + '</td>';
        html += '<td><strong style="color:' + roiColor + ';font-size:14px;">' + b.roiX + '×</strong></td>';
        html += '</tr>';
    }
    html += '</tbody></table>';
    html += '<div style="color:#888;font-size:11px;margin-top:8px;">ROI = (cargas reales generadas) / (total regalado). Verde ≥ 3× = excelente. Amarillo 1-3× = OK. Rojo &lt;1× = perdés plata regalando.</div>';
    container.innerHTML = html;
}

